package com.commandpalette;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Singleton;
import javax.swing.Icon;

/**
 * The answers worked out from the palette, a sum, a tax or an item's price, kept for the side panel's Answers tab
 * so they aren't lost to the chat. They last only as long as the client is open.
 */
@Singleton
class Answers
{
	static final int MAX = 15;

	/**
	 * One answer, and the text that copying it puts on the clipboard.
	 */
	static final class Answer
	{
		private final String text;
		private final String copy;
		private final Icon icon;

		Answer(String text, String copy, Icon icon)
		{
			this.text = text;
			this.copy = copy;
			this.icon = icon;
		}

		String getText()
		{
			return text;
		}

		String getCopy()
		{
			return copy;
		}

		Icon getIcon()
		{
			return icon;
		}
	}

	// added to from the client thread as well as the Swing one
	private final List<Answer> answers = new ArrayList<>();
	private volatile Runnable onChange = () -> {};

	/**
	 * @param onChange run, on any thread, after an answer is added or they are cleared
	 */
	void setOnChange(Runnable onChange)
	{
		this.onChange = onChange;
	}

	void add(String text, Icon icon)
	{
		add(text, text, icon);
	}

	void add(String text, String copy, Icon icon)
	{
		synchronized (answers)
		{
			// asking again moves an answer to the top rather than listing it twice
			answers.removeIf(answer -> answer.getText().equals(text));
			answers.add(0, new Answer(text, copy, icon));
			if (answers.size() > MAX)
			{
				answers.remove(MAX);
			}
		}
		onChange.run();
	}

	/**
	 * Latest first.
	 */
	List<Answer> list()
	{
		synchronized (answers)
		{
			return new ArrayList<>(answers);
		}
	}

	void clear()
	{
		synchronized (answers)
		{
			answers.clear();
		}
		onChange.run();
	}
}

package com.commandpalette;

import java.awt.BorderLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;

/**
 * The side panel's Answers tab: what the palette last worked out, to read again or copy.
 */
class AnswersPanel extends SideTab
{
	private final Answers answers;

	private final JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
	private final JButton clear = new JButton("Clear");

	AnswersPanel(Answers answers)
	{
		this.answers = answers;

		clear.setFont(small());
		clear.addActionListener(e -> answers.clear());
		final JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.add(heading("Answers"), BorderLayout.CENTER);
		header.add(clear, BorderLayout.EAST);

		final JPanel top = new JPanel(new BorderLayout(0, 6));
		top.setOpaque(false);
		top.add(header, BorderLayout.NORTH);
		top.add(note("Sums, taxes, prices and the like that you work out in the palette, latest first, until the"
			+ " client closes."), BorderLayout.SOUTH);

		list.setOpaque(false);
		final JScrollPane scroll = scrolling(list);

		add(top, BorderLayout.NORTH);
		add(scroll, BorderLayout.CENTER);
	}

	@Override
	void refresh()
	{
		list.removeAll();
		final List<Answers.Answer> all = answers.list();
		clear.setEnabled(!all.isEmpty());
		if (all.isEmpty())
		{
			list.add(note("Nothing yet: try typing <b>35m / 4.2k</b> or <b>tax 12m</b> in the palette."));
		}
		for (Answers.Answer answer : all)
		{
			final JPanel row = row();
			final JLabel text = new Wrapping("<html>" + escape(answer.getText()) + "</html>", ROW_TEXT_WIDTH);
			text.setIcon(answer.getIcon());
			text.setForeground(ColorScheme.TEXT_COLOR);
			text.setIconTextGap(6);

			final JButton copy = new JButton(Icons.CLIPBOARD);
			copy.setToolTipText("Copy " + answer.getCopy());
			copy.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
			copy.setContentAreaFilled(false);
			copy.addActionListener(e -> Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(answer.getCopy()), null));

			row.add(text, BorderLayout.CENTER);
			row.add(copy, BorderLayout.EAST);
			list.add(row);
		}
		list.revalidate();
		list.repaint();
	}

	JPanel getList()
	{
		return list;
	}
}

package com.commandpalette;

import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * Arithmetic the way amounts are written in game: 35m / 4.2k, (1.5b - 250m) x 2.
 */
final class Calculator
{
	private static final DecimalFormatSymbols SYMBOLS = DecimalFormatSymbols.getInstance(Locale.ROOT);

	private final String input;
	private int pos;
	private int operators;

	private Calculator(String input)
	{
		this.input = input;
	}

	/**
	 * The value of the expression, or null if the text isn't one. A lone number only counts after an equals sign,
	 * so that typing a world number isn't taken for a sum.
	 */
	static Double evaluate(String text)
	{
		String expression = text.trim();
		final boolean explicit = expression.startsWith("=");
		if (explicit)
		{
			expression = expression.substring(1);
		}

		final Calculator calculator = new Calculator(expression);
		try
		{
			final double value = calculator.sum();
			calculator.skipSpaces();
			if (calculator.pos != expression.length() || (!explicit && calculator.operators == 0)
				|| Double.isNaN(value) || Double.isInfinite(value))
			{
				return null;
			}
			return value;
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	/**
	 * With thousands separators and at most two decimals, followed by the short form for big amounts:
	 * 8,333,333.33 (8.33m)
	 */
	static String format(double value)
	{
		final String full = new DecimalFormat("#,##0.##", SYMBOLS).format(value);
		final double size = Math.abs(value);
		if (size < 100_000)
		{
			return full;
		}
		final DecimalFormat brief = new DecimalFormat("0.##", SYMBOLS);
		final String shortened = size >= 1e9 ? brief.format(value / 1e9) + "b"
			: size >= 1e6 ? brief.format(value / 1e6) + "m"
			: brief.format(value / 1e3) + "k";
		return full + " (" + shortened + ")";
	}

	/**
	 * Just the digits, for pasting elsewhere.
	 */
	static String plain(double value)
	{
		return new DecimalFormat("0.##", SYMBOLS).format(value);
	}

	private double sum()
	{
		double value = product();
		while (true)
		{
			if (take('+'))
			{
				value += product();
			}
			else if (take('-'))
			{
				value -= product();
			}
			else
			{
				return value;
			}
		}
	}

	private double product()
	{
		double value = factor();
		while (true)
		{
			if (take('*') || take('x') || take('X'))
			{
				value *= factor();
			}
			else if (take('/'))
			{
				value /= factor();
			}
			else
			{
				return value;
			}
		}
	}

	private double factor()
	{
		skipSpaces();
		if (peek() == '-')
		{
			pos++;
			return -factor();
		}
		if (peek() == '(')
		{
			pos++;
			final double value = sum();
			skipSpaces();
			if (peek() != ')')
			{
				throw new IllegalArgumentException("unclosed bracket");
			}
			pos++;
			return value;
		}
		return number();
	}

	private double number()
	{
		final StringBuilder digits = new StringBuilder();
		while (Character.isDigit(peek()) || peek() == '.' || peek() == ',')
		{
			if (peek() != ',')
			{
				digits.append(peek());
			}
			pos++;
		}
		// throws NumberFormatException, an IllegalArgumentException, on anything that isn't a number
		double value = Double.parseDouble(digits.toString());
		switch (Character.toLowerCase(peek()))
		{
			case 'k':
				value *= 1e3;
				pos++;
				break;
			case 'm':
				value *= 1e6;
				pos++;
				break;
			case 'b':
				value *= 1e9;
				pos++;
				break;
			default:
				break;
		}
		return value;
	}

	// a binary operator
	private boolean take(char operator)
	{
		skipSpaces();
		if (peek() != operator)
		{
			return false;
		}
		pos++;
		operators++;
		return true;
	}

	private void skipSpaces()
	{
		while (peek() == ' ')
		{
			pos++;
		}
	}

	private char peek()
	{
		return pos < input.length() ? input.charAt(pos) : 0;
	}
}

package com.commandpalette;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanID;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.ImageCapture;
import net.runelite.client.util.LinkBrowser;

/**
 * Odds and ends of the client and the logged in player: a screenshot, things worth copying, and the
 * player's pages on the hiscores and tracking sites.
 */
class ClientCommands
{
	private static final String HISCORES = "https://secure.runescape.com/m=hiscore_oldschool/hiscorepersonal?user1=";
	private static final String GROUP_HISCORES = "https://secure.runescape.com/m=hiscore_oldschool_ironman/group-ironman/view-group?name=";
	private static final String WISE_OLD_MAN = "https://wiseoldman.net/players/";
	private static final String COLLECTION_LOG = "https://templeosrs.com/player/collection-log.php?player=";

	private final Client client;
	private final ClientThread clientThread;
	private final ImageCapture imageCapture;

	@Inject
	ClientCommands(Client client, ClientThread clientThread, ImageCapture imageCapture)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.imageCapture = imageCapture;
	}

	void collect(List<Command> out)
	{
		// the rest need a logged in player; the client refuses to screenshot the login screen
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			out.add(new Command("client:screenshot", "Take screenshot", "", Icons.CAMERA,
				() -> imageCapture.takeScreenshot(null, "", false, true, false)));
			out.add(new Command("client:world", "Copy world", "To clipboard", Icons.CLIPBOARD,
				() -> clientThread.invoke(() -> copy("world", String.valueOf(client.getWorld())))));
			out.add(new Command("client:coordinates", "Copy coordinates", "To clipboard", Icons.CLIPBOARD, () -> clientThread.invoke(() ->
			{
				final Player player = client.getLocalPlayer();
				if (player != null)
				{
					final WorldPoint point = player.getWorldLocation();
					copy("coordinates", point.getX() + ", " + point.getY() + ", " + point.getPlane());
				}
			})));
		}
		profiles(out);
	}

	// pages about the logged in player, and their group if they are a group ironman
	private void profiles(List<Command> out)
	{
		final Player player = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || player == null || player.getName() == null)
		{
			return;
		}

		final String name = player.getName();
		out.add(link("client:hiscores", "Open my hiscores", "Official", HISCORES, name));
		out.add(link("client:wiseoldman", "Open my Wise Old Man profile", "", WISE_OLD_MAN, name));
		out.add(link("client:collectionlog", "Open my collection log", "TempleOSRS", COLLECTION_LOG, name));
		final ClanChannel group = client.getClanChannel(ClanID.GROUP_IRONMAN);
		if (group != null && group.getName() != null)
		{
			out.add(link("client:grouphiscores", "Open my group's hiscores", "Group ironman", GROUP_HISCORES, group.getName()));
		}
	}

	private static Command link(String key, String title, String detail, String url, String name)
	{
		// names come from the game with non-breaking spaces
		final String encoded = URLEncoder.encode(name.replace('\u00A0', ' '), StandardCharsets.UTF_8);
		return new Command(key, title, detail, Icons.LINK, () -> LinkBrowser.browse(url + encoded));
	}

	// on the client thread
	private void copy(String what, String value)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(value), null);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Copied " + what + ": " + value, null);
	}
}

package com.commandpalette;

import javax.swing.Icon;

/**
 * One row of the palette: something that can be found by name and run.
 */
final class Command
{
	private final String key;
	private final String title;
	private final String detail;
	private final Icon icon;
	private final Runnable action;

	/**
	 * @param key    identifies the command from one listing to the next, so that it can be remembered as recently
	 *               used; null for a command that shouldn't be
	 * @param title  what the command is called, e.g. the panel's name
	 * @param detail what running it does, shown dimmed beside the title and searchable too
	 * @param icon   a 16x16 icon, or null
	 * @param action run on the Swing thread once the palette has closed
	 */
	Command(String key, String title, String detail, Icon icon, Runnable action)
	{
		this.key = key;
		this.title = title;
		this.detail = detail;
		this.icon = icon;
		this.action = action;
	}

	/**
	 * A command that isn't remembered as recently used.
	 */
	Command(String title, String detail, Icon icon, Runnable action)
	{
		this(null, title, detail, icon, action);
	}

	String getKey()
	{
		return key;
	}

	String getTitle()
	{
		return title;
	}

	String getDetail()
	{
		return detail;
	}

	Icon getIcon()
	{
		return icon;
	}

	void run()
	{
		action.run();
	}

	@Override
	public String toString()
	{
		return title;
	}
}

package com.commandpalette;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

final class CommandFilter
{
	private CommandFilter()
	{
	}

	/**
	 * The commands matching every word of the query, best matches first and otherwise in their original order.
	 * A query starting with one of {@link Query}'s symbols only finds commands of that kind.
	 */
	static List<Command> filter(List<Command> all, String typed)
	{
		final Query query = Query.parse(typed);
		final List<Command> commands = new ArrayList<>();
		for (Command command : all)
		{
			if (query.allows(command))
			{
				commands.add(command);
			}
		}

		final String needle = query.getText().toLowerCase(Locale.ROOT);
		if (needle.isEmpty())
		{
			return commands;
		}

		final String[] words = needle.split("\\s+");
		final List<Command> matches = new ArrayList<>();
		for (Command command : commands)
		{
			final String haystack = (command.getTitle() + " " + command.getDetail()).toLowerCase(Locale.ROOT);
			boolean everyWord = true;
			for (String word : words)
			{
				everyWord &= haystack.contains(word);
			}
			if (everyWord)
			{
				matches.add(command);
			}
		}
		// List.sort is stable, so equally good matches keep the order they came in
		matches.sort(Comparator.comparingInt(command -> rank(command.getTitle().toLowerCase(Locale.ROOT), needle)));
		return matches;
	}

	private static int rank(String title, String needle)
	{
		if (title.startsWith(needle))
		{
			return 0;
		}
		if (title.contains(" " + needle))
		{
			return 1;
		}
		if (title.contains(needle))
		{
			return 2;
		}
		return 3;
	}
}

package com.commandpalette;

import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(CommandPaletteConfig.GROUP)
public interface CommandPaletteConfig extends Config
{
	String GROUP = "commandpalette";

	@ConfigSection(
		name = "Commands",
		description = "Which commands the palette lists",
		position = 10
	)
	String commandsSection = "commands";

	@ConfigSection(
		name = "Help",
		description = "How to find out what the palette can do",
		position = 20
	)
	String helpSection = "help";

	@ConfigItem(
		keyName = "hotkey",
		name = "Open hotkey",
		description = "Opens the command palette. Only the key is used; the modifier comes from the next setting."
			+ " Type to filter, Up/Down to move, Enter to run the selected command, Esc or the hotkey again to cancel.",
		position = 0
	)
	default Keybind hotkey()
	{
		return new Keybind(KeyEvent.VK_P, 0);
	}

	@ConfigItem(
		keyName = "requireModifier",
		name = "Require Ctrl/Cmd",
		description = "Require the platform modifier (Cmd on Mac, Ctrl on Windows) together with the open hotkey."
			+ " Follows the Platform Keys plugin's key profile when that plugin is on.",
		position = 1
	)
	default boolean requireModifier()
	{
		return true;
	}

	@ConfigItem(
		keyName = "recentFirst",
		name = "Recently used first",
		description = "List the last few commands you ran in a section of their own before the rest, latest first",
		position = 2
	)
	default boolean recentFirst()
	{
		return true;
	}

	@Range(
		min = 1,
		max = RecentCommands.MAX
	)
	@ConfigItem(
		keyName = "recentCount",
		name = "Recently used count",
		description = "How many recently used commands to list first",
		position = 3
	)
	default int recentCount()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "showIcons",
		name = "Show icons",
		description = "Show an icon before each command's name, and a clock after a recently used one",
		position = 4
	)
	default boolean showIcons()
	{
		return true;
	}

	String SIDE_PANEL_KEY = "sidePanel";

	@ConfigItem(
		keyName = SIDE_PANEL_KEY,
		name = "Side panel",
		description = "Add a Command Palette panel to the sidebar, with tabs for running timers, this session's xp,"
			+ " the palette's recent answers, your pinned commands and commands of your own",
		position = 5
	)
	default boolean sidePanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "panelCommands",
		name = "Side panels",
		description = "List every side panel, to open it, and commands to close the open one and to hide or show the sidebar",
		section = commandsSection,
		position = 0
	)
	default boolean panelCommands()
	{
		return true;
	}

	@ConfigItem(
		keyName = "clientCommands",
		name = "Client utilities",
		description = "Take a screenshot, copy your world or coordinates, sum up your session, and open your"
			+ " hiscores and tracker pages",
		section = commandsSection,
		position = 1
	)
	default boolean clientCommands()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lookupCommands",
		name = "Lookups and sums",
		description = "Work out a sum such as 35m / 4.2k, the odds of a dry streak with \"dry 1/512 600\","
			+ " the Grand Exchange's tax with \"tax 12m\" or game ticks as time with \"ticks 250\","
			+ " and when logged in look up an item with \"alch rune platebody\""
			+ " or the xp left to a level with \"xp 92 slayer\"",
		section = commandsSection,
		position = 2
	)
	default boolean lookupCommands()
	{
		return true;
	}

	@ConfigItem(
		keyName = "wikiSearch",
		name = "Wiki search",
		description = "Offer to search the wiki for whatever is typed, after the commands matching it."
			+ " Starting with ? searches the wiki whether or not this is on.",
		section = commandsSection,
		position = 6
	)
	default boolean wikiSearch()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pluginCommands",
		name = "Plugins on/off",
		description = "List every plugin, to turn it on or off",
		section = commandsSection,
		position = 3
	)
	default boolean pluginCommands()
	{
		return false;
	}

	@ConfigItem(
		keyName = "confirmPluginToggle",
		name = "Confirm plugins on/off",
		description = "Ask before turning a plugin on or off from the palette",
		section = commandsSection,
		position = 4
	)
	default boolean confirmPluginToggle()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pluginSettingsCommands",
		name = "Plugin settings",
		description = "List every plugin that has settings, to open them in the Configuration panel",
		section = commandsSection,
		position = 5
	)
	default boolean pluginSettingsCommands()
	{
		return false;
	}

	@ConfigItem(
		keyName = "timerCommands",
		name = "Timers",
		description = "Start a timer with \"timer 5m herb run\", which sends a notification when it runs out."
			+ " A timer that is running can be cancelled whether or not this is on.",
		section = commandsSection,
		position = 8
	)
	default boolean timerCommands()
	{
		return true;
	}

	@ConfigItem(
		keyName = "help",
		name = "Help command",
		description = "Where to find what can be typed into the palette",
		section = helpSection,
		position = 0
	)
	default String help()
	{
		return "Open the palette, type help and press Enter. The Help command lists every command.";
	}

	String SEEN_VERSION_KEY = "lastSeenVersion";

	@ConfigItem(
		keyName = SEEN_VERSION_KEY,
		name = "",
		description = "",
		hidden = true
	)
	default String lastSeenVersion()
	{
		return "";
	}
}

package com.commandpalette;

