import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Command Palette",
	description = "A hotkey-driven, searchable list of commands: jump to any side panel, open plugin settings",
	tags = {"command", "palette", "sidebar", "panel", "hotkey", "keyboard", "search", "navigation"}
)
public class CommandPalettePlugin extends Plugin implements KeyListener, PalettePanel.Listener
{
	private static final Logger log = LoggerFactory.getLogger(CommandPalettePlugin.class);

	private static final int NO_KEY = KeyEvent.VK_UNDEFINED;
	static final String SIDE_PANEL_KIND = "sidepanel:";

	// The latest version with something new to tell of, and what is said about it, once, at the next login.
	// A release with nothing to announce changes the version and leaves the news empty.
	static final String NEWS_VERSION = "1.0.0";
	static final String NEWS = "";

	@Inject
	private CommandPaletteConfig config;

	@Inject
	private Hotkey hotkey;

	@Inject
	private GameTyping gameTyping;

	@Inject
	private SidebarCommands sidebarCommands;

	@Inject
	private ClientCommands clientCommands;

	@Inject
	private SessionCommands sessionCommands;

	@Inject
	private TypedCommands typedCommands;

	@Inject
	private HelpCommand helpCommand;

	@Inject
	private PluginCommands pluginCommands;

	@Inject
	private RecentCommands recentCommands;

	@Inject
	private PinnedCommands pinnedCommands;

	@Inject
	private CustomCommands customCommands;

	@Inject
	private Answers answers;

	@Inject
	private VariableResolver variables;

	// counts game ticks, for what is read every few
	private int ticks;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private Timers timers;

	@Inject
	private EventBus eventBus;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	private PalettePanel panel;
	private SidePanel sidePanel;
	// the side panel's place in the sidebar, and whether it is in the sidebar
	private NavigationButton sideButton;
	private boolean sideButtonShown;
	// A first install has no news to catch up on: it is welcomed instead, at the next login
	private boolean welcomePending;
	private JDialog dialog;
	// the hotkey's key while it is still held down after opening or closing the palette
	private int heldKey = NO_KEY;

	@Provides
	CommandPaletteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CommandPaletteConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Nothing saved at all means a first install
		if (config.lastSeenVersion().isEmpty()
			&& configManager.getConfigurationKeys(CommandPaletteConfig.GROUP + ".").isEmpty())
		{
			configManager.setConfiguration(CommandPaletteConfig.GROUP, CommandPaletteConfig.SEEN_VERSION_KEY,
				NEWS_VERSION);
			welcomePending = true;
		}
		// Only keys pressed on the game reach this: the palette's own search closes it on the hotkey itself
		keyManager.registerKeyListener(this);
		eventBus.register(sessionCommands);
		// for Ground Marker Variables' answers
		eventBus.register(variables);
		createSidePanel();
		syncSidePanel();
	}

	private void createSidePanel()
	{
		final Map<SidePanel.Tab, SideTab> tabs = new EnumMap<>(SidePanel.Tab.class);
		tabs.put(SidePanel.Tab.TIMERS, new TimersPanel(timers::running, timers::start));
		tabs.put(SidePanel.Tab.SESSION, new SessionPanel(sessionCommands::snapshot,
			skill -> Icons.of(skillIconManager.getSkillImage(skill, true))));
		tabs.put(SidePanel.Tab.ANSWERS, new AnswersPanel(answers));
		tabs.put(SidePanel.Tab.PINNED, new PinnedPanel(this::collectCommands, this::run, pinnedCommands::load,
			pinnedCommands::toggle, recentCommands::load));
		tabs.put(SidePanel.Tab.CUSTOM, new CustomPanel(customCommands::load, customCommands::save,
			this::collectCommands));
		sidePanel = new SidePanel(tabs, hotkey::describe, () -> helpCommand.command().run());
		answers.setOnChange(() -> SwingUtilities.invokeLater(() -> sidePanel.refreshIfShowing(SidePanel.Tab.ANSWERS)));
		sideButton = NavigationButton.builder()
			.tooltip(SidePanel.NAME)
			.icon(Icons.PROMPT.image())
			.priority(8)
			.panel(sidePanel)
			.build();
	}

	// The help in the settings is in text boxes, which can be typed in: put back whatever is changed
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CommandPaletteConfig.GROUP.equals(event.getGroup()) && event.getKey().startsWith("help")
			&& event.getNewValue() != null)
		{
			configManager.unsetConfiguration(CommandPaletteConfig.GROUP, event.getKey());
		}
		if (CommandPaletteConfig.GROUP.equals(event.getGroup())
			&& event.getKey().equals(CommandPaletteConfig.SIDE_PANEL_KEY))
		{
			SwingUtilities.invokeLater(this::syncSidePanel);
		}
	}

	// Another profile has settings, recently used commands and pins of its own, which no config change is sent for
	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		SwingUtilities.invokeLater(() ->
		{
			syncSidePanel();
			if (sidePanel != null)
			{
				sidePanel.refreshIfShowing(sidePanel.getSelected());
			}
		});
	}

	// the side panel is in the sidebar while the setting says so
	private void syncSidePanel()
	{
		if (config.sidePanel() && !sideButtonShown)
		{
			clientToolbar.addNavigation(sideButton);
			sideButtonShown = true;
		}
		else if (!config.sidePanel() && sideButtonShown)
		{
			clientToolbar.removeNavigation(sideButton);
			sideButtonShown = false;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// the previews are of a player who has logged out
			customCommands.clearPreviews();
		}
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		// This state comes again after every loading screen, so each message is marked as given before it is
		if (welcomePending)
		{
			welcomePending = false;
			say(welcome(hotkey.describe()));
		}
		else if (!NEWS_VERSION.equals(config.lastSeenVersion()))
		{
			configManager.setConfiguration(CommandPaletteConfig.GROUP, CommandPaletteConfig.SEEN_VERSION_KEY,
				NEWS_VERSION);
			if (!NEWS.isEmpty())
			{
				say(NEWS);
			}
		}
	}

	// the previews of the custom commands, every few ticks
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (ticks++ % CustomCommands.PREVIEW_TICKS == 0)
		{
			customCommands.refreshPreviews(text -> variables.resolve(text, false));
		}
	}

	private void say(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(message).build())
			.build());
	}

	/**
	 * What a first install is told: how to open the palette.
	 *
	 * @param keys the hotkey, "Ctrl+P", or null if it has no name to give
	 */
	static String welcome(String keys)
	{
		return "Command Palette: press " + (keys == null ? "its hotkey" : keys) + " on the game to open"
			+ " a side panel or a plugin's settings by typing its name. Type help to see the rest.";
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(this);
		eventBus.unregister(sessionCommands);
		eventBus.unregister(variables);
		clientToolbar.removeNavigation(sideButton);
		sideButtonShown = false;
		welcomePending = false;
		sessionCommands.reset();
		timers.reset();
		answers.setOnChange(() -> {});
		answers.clear();
		SwingUtilities.invokeLater(() ->
		{
			sidePanel.stop();
			if (dialog != null)
			{
				dialog.dispose();
				dialog = null;
				panel = null;
			}
			heldKey = NO_KEY;
		});
	}

	@Override
	public boolean isEnabledOnLoginScreen()
	{
		return true;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!hotkey.matches(e))
		{
			heldKey = NO_KEY;
			return;
		}
		// Key repeat while the hotkey is held shouldn't flick the palette open and shut
		if (heldKey != e.getKeyCode() && !toggle(e))
		{
			return;
		}
		heldKey = e.getKeyCode();
		e.consume();
	}

	// Swallow the rest of the hotkey's own keystroke so it isn't typed into the search or the game
	@Override
	public void keyTyped(KeyEvent e)
	{
		if (heldKey != NO_KEY)
		{
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (heldKey != NO_KEY && e.getKeyCode() == heldKey)
		{
			heldKey = NO_KEY;
			e.consume();
		}
	}

	/**
	 * The palette's own search closes it on the hotkey, unless it is a character to type there: without Ctrl/Cmd.
	 */
	@Override
	public boolean isHotkey(KeyEvent e)
	{
		return (hotkey.hasModifier() || e.isActionKey()) && hotkey.matches(e);
	}

	private boolean toggle(KeyEvent e)
	{
		// Without Ctrl/Cmd, a hotkey that is also a character belongs to whatever is being typed in on the game:
		// the chat, or an input box of the game's
		if (!hotkey.hasModifier() && !e.isActionKey() && gameTyping.isTyping())
		{
			return false;
		}
		if (isOpen())
		{
			cancel();
			return true;
		}
		return open();
	}

	private boolean isOpen()
	{
		return dialog != null && dialog.isVisible();
	}

	private boolean open()
	{
		final JFrame frame = Sidebar.findClientFrame();
		if (frame == null)
		{
			return false;
		}

		final List<Command> commands = collect(frame);
		// for a custom command that takes text, before the recently used are taken out of the list
		final Map<String, Command> byKey = byKey(commands);
		if (dialog == null)
		{
			createDialog(frame);
		}
		// the pinned keep their place after the recently used, rather than moving up among them when used
		final List<Command> pinned = RecentCommands.pick(commands, pinnedCommands.load(), PinnedCommands.MAX);
		commands.removeAll(pinned);
		final List<Command> recent = config.recentFirst()
			? RecentCommands.pick(commands, recentCommands.load(), config.recentCount())
			: Collections.emptyList();
		commands.removeAll(recent);
		typedCommands.forgetVariables();
		panel.show(recent, pinned, commands, typed ->
		{
			final List<Command> typedOnes = new ArrayList<>(customCommands.forQuery(typed, byKey::get));
			typedOnes.addAll(typedCommands.forQuery(typed));
			return typedOnes;
		}, config.showIcons());
		dialog.pack();
		dialog.setLocation(location(frame));
		dialog.setVisible(true);
		panel.focusSearch();
		return true;
	}

	// for the side panel's Pinned tab
	private List<Command> collectCommands()
	{
		final JFrame frame = Sidebar.findClientFrame();
		return frame == null ? Collections.emptyList() : collect(frame);
	}

	/**
	 * Every command of the groups turned on, as things stand.
	 */
	private List<Command> collect(JFrame frame)
	{
		final List<Command> commands = new ArrayList<>();
		if (config.panelCommands())
		{
			sidebarCommands.collect(frame, commands);
		}
		if (config.sidePanel())
		{
			for (SidePanel.Tab tab : SidePanel.Tab.values())
			{
				commands.add(new Command(SIDE_PANEL_KIND + tab.name().toLowerCase(Locale.ROOT), tab.getTitle(),
					"Open in the " + SidePanel.NAME + " panel", tab.getIcon(), () -> showTab(frame, tab)));
			}
		}
		if (config.clientCommands())
		{
			clientCommands.collect(commands);
			sessionCommands.collect(commands);
		}
		timers.collect(commands);
		commands.add(helpCommand.command());
		if (config.pluginCommands())
		{
			pluginCommands.collect(commands);
		}
		if (config.pluginSettingsCommands())
		{
			pluginCommands.collectSettings(commands);
		}
		// last, so that they can run any of the others
		customCommands.collect(commands, byKey(commands)::get);
		return commands;
	}

	/**
	 * The commands a custom one can run, by key.
	 */
	private static Map<String, Command> byKey(List<Command> commands)
	{
		final Map<String, Command> byKey = new HashMap<>();
		for (Command command : commands)
		{
			if (CustomCommands.canRun(command))
			{
				byKey.putIfAbsent(command.getKey(), command);
			}
		}
		return byKey;
	}

	private void showTab(JFrame frame, SidePanel.Tab tab)
	{
		sidePanel.select(tab);
		sidebarCommands.open(frame, SidePanel.NAME);
	}

	private void createDialog(JFrame frame)
	{
		dialog = new JDialog(frame);
		panel = new PalettePanel(this);
		typedCommands.setOnIconLoaded(panel::repaint);
		typedCommands.setOnVariablesResolved(panel::requery);
		dialog.setUndecorated(true);
		dialog.getRootPane().setWindowDecorationStyle(JRootPane.NONE);
		dialog.setResizable(false);
		dialog.setContentPane(panel);
		dialog.addWindowFocusListener(new WindowAdapter()
		{
			@Override
			public void windowLostFocus(WindowEvent e)
			{
				cancel();
			}
		});
	}

	// near the top of the game, clear of the sidebar
	private Point location(JFrame frame)
	{
		final Container content = frame.getContentPane();
		final JTabbedPane sidebar = Sidebar.find(frame);
		final int sidebarWidth = sidebar != null && sidebar.isVisible() ? sidebar.getWidth() : 0;
		final Point origin = content.getLocationOnScreen();
		return new Point(
			origin.x + Math.max(0, (content.getWidth() - sidebarWidth - dialog.getWidth()) / 2),
			origin.y + content.getHeight() / 6);
	}

	@Override
	public void run(Command command)
	{
		// close first, so that the command acts on the client window and not on the palette
		cancel();
		recentCommands.record(command);
		try
		{
			command.run();
		}
		catch (RuntimeException ex)
		{
			log.warn("Command \"{}\" failed", command.getTitle(), ex);
		}
	}

	@Override
	public void cancel()
	{
		if (isOpen())
		{
			dialog.setVisible(false);
		}
	}

	@Override
	public void resized()
	{
		if (dialog != null)
		{
			dialog.pack();
		}
	}
}

package com.commandpalette;

import java.util.Collection;
import java.util.Locale;
import java.util.Objects;
import java.util.function.Function;

/**
 * A command the user has made from one of the palette's own actions, saved as json.
 */
final class CustomCommand
{
	/**
	 * What a custom command does. Each is something the palette can already do: none of them sends anything to the
	 * game.
	 */
	enum Action
	{
		LINK("Open a link"),
		TIMER("Start a timer"),
		COMMAND("Run a palette command"),
		COPY("Copy text"),
		SHOW("Show text in the chat");

		private final String label;

		Action(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	// in a link, where what is typed after the command's name goes
	static final String TEXT = "{text}";
	static final int MAX_NAME = 40;

	private final String name;
	private final Action action;
	private final String value;

	CustomCommand(String name, Action action, String value)
	{
		this.name = name;
		this.action = action;
		this.value = value;
	}

	String getName()
	{
		return name;
	}

	Action getAction()
	{
		return action;
	}

	/**
	 * The link, the timer ("80m herb run"), the key of the palette command, or the text to copy or show, any of
	 * which but the timer and the command can have variables in it: "{rsn}".
	 */
	String getValue()
	{
		return value;
	}

	String getKey()
	{
		return CustomCommands.KIND + name.toLowerCase(Locale.ROOT);
	}

	// commands are read afresh from the settings each time, so they are told apart by what they are
	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof CustomCommand))
		{
			return false;
		}
		final CustomCommand that = (CustomCommand) other;
		return name.equals(that.name) && action == that.action && value.equals(that.value);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(name, action, value);
	}

	/**
	 * Whether what is typed after its name is put into its link or text.
	 */
	boolean takesText()
	{
		return action != Action.TIMER && action != Action.COMMAND && value.contains(TEXT);
	}

	/**
	 * What it does, as the palette shows it beside the name.
	 *
	 * @param titleOf the title of the palette command with that key, or null if there is none now
	 */
	String describe(Function<String, String> titleOf)
	{
		switch (action)
		{
			case LINK:
				return takesText() ? "Search " + host(value) : "Open " + host(value);
			case TIMER:
				final Timers.Request timer = Timers.parse(value);
				return timer == null ? "Timer" : "Start " + timer.describe();
			case COMMAND:
				final String title = titleOf.apply(value);
				return title == null ? "Command not available now" : "Run " + title;
			case SHOW:
				return "Show " + value;
			default:
				return "Copy " + value;
		}
	}

	// "prices.runescape.wiki", for describing a link
	static String host(String url)
	{
		String host = url.replaceFirst("^[a-zA-Z]+://", "");
		final int end = host.indexOf('/');
		host = end < 0 ? host : host.substring(0, end);
		return host.startsWith("www.") ? host.substring(4) : host;
	}

	/**
	 * What is wrong with it, to be put right before it is saved, or null if nothing is.
	 *
	 * @param others  the names of the other custom commands
	 * @param exists  whether there is a palette command with that key
	 */
	static String problem(String name, Action action, String value, Collection<String> others,
		Function<String, Boolean> exists)
	{
		final String trimmed = name.trim();
		if (trimmed.isEmpty())
		{
			return "Give it a name to type in the palette.";
		}
		if (trimmed.length() > MAX_NAME)
		{
			return "Keep the name to " + MAX_NAME + " characters.";
		}
		for (String other : others)
		{
			if (other.equalsIgnoreCase(trimmed))
			{
				return "There is already a command called " + other + ".";
			}
		}
		final String v = value.trim();
		switch (action)
		{
			case LINK:
				return v.matches("(?i)https?://[^\\s/]+.*") ? null
					: "A link starts with https:// and has no spaces; put " + TEXT + " where the search goes.";
			case TIMER:
				return Timers.parse(v) != null ? null
					: "Start with a length of time, up to a day, then what it is for: 80m herb run.";
			case COMMAND:
				return exists.apply(v) ? null : "Pick a command to run.";
			case SHOW:
				return v.isEmpty() ? "Type the text to show." : null;
			default:
				return v.isEmpty() ? "Type the text to copy." : null;
		}
	}
}

package com.commandpalette;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.inject.Inject;
import javax.swing.Icon;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.LinkBrowser;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The commands the user has made in the side panel's Custom tab, kept in this plugin's settings of each profile.
 */
class CustomCommands
{
	private static final Logger log = LoggerFactory.getLogger(CustomCommands.class);

	static final String KIND = "custom:";
	static final int MAX = 100;

	// how often, in game ticks, what the commands with variables would show or copy is read again
	static final int PREVIEW_TICKS = 5;

	/**
	 * Commands to start from, most of them with the player's name filled in.
	 */
	static final List<CustomCommand> EXAMPLES = List.of(
		new CustomCommand("ge", CustomCommand.Action.LINK, "https://prices.runescape.wiki/osrs/all-items?search={text}"),
		new CustomCommand("wom", CustomCommand.Action.LINK, "https://wiseoldman.net/players/{rsn}"),
		new CustomCommand("hiscores", CustomCommand.Action.LINK,
			"https://secure.runescape.com/m=hiscore_oldschool/hiscorepersonal?user1={rsn}"),
		new CustomCommand("brag", CustomCommand.Action.SHOW, "{rsn}: total {lvl_total}, combat {lvl_combat}"),
		new CustomCommand("temple", CustomCommand.Action.LINK, "https://templeosrs.com/player/overview.php?player={rsn}"),
		new CustomCommand("clog", CustomCommand.Action.LINK,
			"https://templeosrs.com/player/collection-log.php?player={rsn}"),
		new CustomCommand("rsn", CustomCommand.Action.COPY, "{rsn}"));

	private static final String CONFIG_KEY = "customCommands";

	private final ConfigManager configManager;
	private final Gson gson;
	private final TypedCommands typedCommands;
	private final VariableResolver variables;
	// what each command that shows or copies text with variables in it would, by name, read every few ticks
	private volatile Map<String, String> previews = Collections.emptyMap();

	@Inject
	CustomCommands(ConfigManager configManager, Gson gson, TypedCommands typedCommands, VariableResolver variables)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.typedCommands = typedCommands;
		this.variables = variables;
	}

	List<CustomCommand> load()
	{
		return parse(gson, configManager.getConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY));
	}

	void save(List<CustomCommand> commands)
	{
		if (commands.isEmpty())
		{
			configManager.unsetConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY);
		}
		else
		{
			configManager.setConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY, toJson(gson, commands));
		}
	}

	/**
	 * The saved commands, leaving out any that can't be read.
	 */
	static List<CustomCommand> parse(Gson gson, String json)
	{
		final List<CustomCommand> commands = new ArrayList<>();
		if (json == null || json.isEmpty())
		{
			return commands;
		}
		try
		{
			for (JsonElement element : gson.fromJson(json, JsonArray.class))
			{
				final JsonObject saved = element.getAsJsonObject();
				final CustomCommand.Action action = CustomCommand.Action.valueOf(saved.get("action").getAsString());
				commands.add(new CustomCommand(saved.get("name").getAsString(), action, saved.get("value").getAsString()));
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Couldn't read the custom commands", e);
		}
		return commands;
	}

	static String toJson(Gson gson, List<CustomCommand> commands)
	{
		final JsonArray saved = new JsonArray();
		for (CustomCommand command : commands)
		{
			final JsonObject object = new JsonObject();
			object.addProperty("name", command.getName());
			object.addProperty("action", command.getAction().name());
			object.addProperty("value", command.getValue());
			saved.add(object);
		}
		return gson.toJson(saved);
	}

	/**
	 * A palette command for each custom one.
	 *
	 * @param find the palette command with that key, or null if there is none now
	 */
	void collect(List<Command> out, Function<String, Command> find)
	{
		for (CustomCommand custom : load())
		{
			out.add(new Command(custom.getKey(), custom.getName(), describe(custom, find), icon(custom, find),
				() -> run(custom, "", find)));
		}
	}

	/**
	 * For one that takes text, a command to run it with whatever is typed after its name: "ge abyssal whip".
	 */
	List<Command> forQuery(String typed, Function<String, Command> find)
	{
		final String text = typed.trim();
		final List<Command> commands = new ArrayList<>();
		for (CustomCommand custom : load())
		{
			final String prefix = custom.getName().toLowerCase(Locale.ROOT) + " ";
			if (custom.takesText() && text.toLowerCase(Locale.ROOT).startsWith(prefix)
				&& text.length() > prefix.length())
			{
				final String rest = text.substring(prefix.length()).trim();
				commands.add(new Command(custom.getName() + ": " + rest, describe(custom, find), Icons.LINK,
					() -> run(custom, rest, find)));
			}
		}
		return commands;
	}

	/**
	 * Reads again what each command that shows or copies text with variables in it would, on the client thread.
	 *
	 * @param resolve fills in the variables of a text
	 */
	void refreshPreviews(Function<String, String> resolve)
	{
		final Map<String, String> next = new HashMap<>();
		for (CustomCommand custom : load())
		{
			if (isPreviewed(custom))
			{
				next.put(custom.getName(), resolve.apply(custom.getValue()));
			}
		}
		previews = next;
	}

	/**
	 * Forgets the previews, which are of a player who has logged out.
	 */
	void clearPreviews()
	{
		previews = Collections.emptyMap();
	}

	private static boolean isPreviewed(CustomCommand custom)
	{
		return (custom.getAction() == CustomCommand.Action.SHOW || custom.getAction() == CustomCommand.Action.COPY)
			&& VariableResolver.hasVariables(custom.getValue());
	}

	// what it shows or copies with its variables filled in, when they have been read
	private String describe(CustomCommand custom, Function<String, Command> find)
	{
		final String preview = isPreviewed(custom) ? previews.get(custom.getName()) : null;
		if (preview != null && !preview.equals(custom.getValue()))
		{
			return (custom.getAction() == CustomCommand.Action.SHOW ? "Show " : "Copy ") + preview;
		}
		return custom.describe(key ->
		{
			final Command target = find.apply(key);
			return target == null ? null : target.getTitle();
		});
	}

	private static Icon icon(CustomCommand custom, Function<String, Command> find)
	{
		switch (custom.getAction())
		{
			case LINK:
				return Icons.LINK;
			case TIMER:
				return Icons.TIMER;
			case COMMAND:
				final Command target = find.apply(custom.getValue());
				return target == null || target.getIcon() == null ? Icons.PROMPT : target.getIcon();
			case SHOW:
				return Icons.CHAT;
			default:
				return Icons.CLIPBOARD;
		}
	}

	private void run(CustomCommand custom, String text, Function<String, Command> find)
	{
		switch (custom.getAction())
		{
			case LINK:
				// each variable's value is made safe for a link, and then what was typed is
				fill(custom.getValue(), true, url -> LinkBrowser.browse(link(url, text)));
				break;
			case TIMER:
				final Timers.Request timer = Timers.parse(custom.getValue());
				if (timer != null)
				{
					typedCommands.startTimer(timer);
				}
				break;
			case COMMAND:
				final Command target = find.apply(custom.getValue());
				if (target != null)
				{
					target.run();
				}
				break;
			case SHOW:
				fill(withText(custom.getValue(), text), false, shown -> typedCommands.show(shown, Icons.CHAT));
				break;
			default:
				fill(withText(custom.getValue(), text), false, copied ->
					Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(copied), null));
				break;
		}
	}

	// the variables are read on the client thread, so only text that has some waits for it
	private void fill(String text, boolean encode, Consumer<String> then)
	{
		if (VariableResolver.hasVariables(text))
		{
			variables.resolveLater(text, encode, then);
		}
		else
		{
			then.accept(text);
		}
	}

	static String withText(String value, String text)
	{
		return value.replace(CustomCommand.TEXT, text);
	}

	/**
	 * The link with the text in place of {text}, made safe to put in a link.
	 */
	static String link(String url, String text)
	{
		return url.replace(CustomCommand.TEXT, URLEncoder.encode(text, StandardCharsets.UTF_8).replace("+", "%20"));
	}

	/**
	 * Whether a palette command can be run by a custom one: not another custom one, which could go round in a loop.
	 */
	static boolean canRun(Command command)
	{
		return command.getKey() != null && !command.getKey().startsWith(KIND);
	}

	static List<CustomCommand> without(List<CustomCommand> commands, CustomCommand removed)
	{
		final List<CustomCommand> rest = new ArrayList<>(commands);
		rest.remove(removed);
		return Collections.unmodifiableList(rest);
	}
}

