	static final int SIZE = 16;

	private static final int UNITS = 64;

	/**
	 * Draw the icon within 64 by 64, in the colour and the round 6 unit line already set.
	 */
	abstract void draw(Graphics2D g);

	@Override
	public void paintIcon(Component c, Graphics graphics, int x, int y)
	{
		final Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.translate(x, y);
		g.scale((double) SIZE / UNITS, (double) SIZE / UNITS);
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.setStroke(new BasicStroke(6, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		draw(g);
		g.dispose();
	}

	@Override
	public int getIconWidth()
	{
		return SIZE;
	}

	@Override
	public int getIconHeight()
	{
		return SIZE;
	}

	/**
	 * The icon drawn once into an image, for a sidebar button.
	 */
	BufferedImage image()
	{
		final BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		paintIcon(null, g, 0, 0);
		g.dispose();
		return image;
	}

	/**
	 * An icon of the image shrunk to fit, whatever its size. It is drawn from the image each time, so one that is
	 * still loading shows up once it has and the list is repainted.
	 */
	static Icon of(Image image)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics graphics, int x, int y)
			{
				final int width = image.getWidth(null);
				final int height = image.getHeight(null);
				if (width <= 0 || height <= 0)
				{
					return;
				}
				final double scale = Math.min(1, Math.min((double) SIZE / width, (double) SIZE / height));
				final int w = (int) Math.round(width * scale);
				final int h = (int) Math.round(height * scale);
				final Graphics2D g = (Graphics2D) graphics.create();
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				g.drawImage(image, x + (SIZE - w) / 2, y + (SIZE - h) / 2, w, h, null);
				g.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return SIZE;
			}

			@Override
			public int getIconHeight()
			{
				return SIZE;
			}
		};
	}

	private static Path2D pinHead()
	{
		final Path2D head = new Path2D.Double();
		head.moveTo(22, 8);
		head.lineTo(42, 8);
		head.lineTo(38, 26);
		head.lineTo(46, 36);
		head.lineTo(18, 36);
		head.lineTo(26, 26);
		head.closePath();
		return head;
	}

	private static void line(Graphics2D g, double x1, double y1, double x2, double y2)
	{
		g.draw(new Line2D.Double(x1, y1, x2, y2));
	}

	// centred in the square
	private static void text(Graphics2D g, String text, int size)
	{
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, size));
		final FontMetrics metrics = g.getFontMetrics();
		g.drawString(text, (UNITS - metrics.stringWidth(text)) / 2f,
			(UNITS - metrics.getHeight()) / 2f + metrics.getAscent());
	}
}

package com.commandpalette;

import java.util.Locale;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * A skill and optionally a level to reach in it, as typed: "92 slayer", "slay 92", "runecraft".
 */
final class LevelGoal
{
	private final Skill skill;
	private final int level;

	private LevelGoal(Skill skill, int level)
	{
		this.skill = skill;
		this.level = level;
	}

	/**
	 * @return null unless the text is one skill, by name or the start of it, with at most one level from 2 to 126
	 */
	static LevelGoal parse(String text)
	{
		Skill skill = null;
		int level = 0;
		for (String word : text.trim().toLowerCase(Locale.ROOT).split("\\s+"))
		{
			if (word.matches("\\d{1,3}"))
			{
				final int number = Integer.parseInt(word);
				if (level != 0 || number < 2 || number > Experience.MAX_VIRT_LEVEL)
				{
					return null;
				}
				level = number;
			}
			else
			{
				final Skill named = skillStarting(word);
				if (skill != null || named == null)
				{
					return null;
				}
				skill = named;
			}
		}
		return skill == null ? null : new LevelGoal(skill, level);
	}

	private static Skill skillStarting(String word)
	{
		Skill found = null;
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL && skill.getName().toLowerCase(Locale.ROOT).startsWith(word))
			{
				if (found != null)
				{
					// "s" could be several skills
					return null;
				}
				found = skill;
			}
		}
		return found;
	}

	Skill getSkill()
	{
		return skill;
	}

	/**
	 * The level asked for, or 0 if none was.
	 */
	int getLevel()
	{
		return level;
	}
}

package com.commandpalette;

import java.awt.BorderLayout;
