/**
 * The palette itself: a search field over the list of matching commands.
 */
class PalettePanel extends JPanel
{
	interface Listener
	{
		void run(Command command);

		void cancel();

		/**
		 * The list grew or shrank, so the panel's preferred size changed.
		 */
		void resized();

		/**
		 * Whether the key closes the palette as the hotkey that opened it.
		 */
		default boolean isHotkey(KeyEvent e)
		{
			return false;
		}
	}

	private static final int WIDTH = 320;
	private static final int ROW_HEIGHT = 24;
	private static final int MAX_ROWS = 12;

	private static final Border ROW_BORDER = BorderFactory.createEmptyBorder(0, 6, 0, 6);
	// a line above the first row of a section
	private static final Border SECTION_BORDER = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR),
		BorderFactory.createEmptyBorder(0, 6, 1, 6));

	private static final Icon NO_ICON = new Icon()
	{
		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
		}

		@Override
		public int getIconWidth()
		{
			return Icons.SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return Icons.SIZE;
		}
	};

	private final Listener listener;
	private final JTextField search = new JTextField();
	private final DefaultListModel<Command> model = new DefaultListModel<>();
	private final JList<Command> list = new JList<>(model);
	private final JScrollPane scroll = new JScrollPane(list);
	private final JLabel empty = new JLabel("No matching commands", SwingConstants.CENTER);

	private List<Command> recent = Collections.emptyList();
	private List<Command> pinned = Collections.emptyList();
	private List<Command> commands = Collections.emptyList();
	// the rows that start a section after the first, the pinned or the rest, when the list is in sections
	private Set<Integer> sectionStarts = Collections.emptySet();
	private boolean showIcons = true;
	private Function<String, List<Command>> forQuery = query -> Collections.emptyList();

	PalettePanel(Listener listener)
	{
		this.listener = listener;

		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 6, 6, 6)));

		search.putClientProperty("JTextField.placeholderText", "Type a command");
		// Tab moves through the list rather than out of the field
		search.setFocusTraversalKeysEnabled(false);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				refilter();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				refilter();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				refilter();
			}
		});
		search.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				PalettePanel.this.keyPressed(e);
			}

		});

		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setFocusable(false);
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		list.setFixedCellHeight(ROW_HEIGHT);
		list.setFixedCellWidth(WIDTH);
		list.setCellRenderer(new Row());
		final MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				final int row = rowAt(e);
				if (row >= 0)
				{
					list.setSelectedIndex(row);
				}
			}

			@Override
			public void mouseClicked(MouseEvent e)
			{
				final int row = rowAt(e);
				if (row >= 0 && e.getButton() == MouseEvent.BUTTON1)
				{
					listener.run(model.get(row));
				}
			}
		};
		list.addMouseListener(mouse);
		list.addMouseMotionListener(mouse);

		scroll.setBorder(null);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);

		empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		empty.setPreferredSize(new Dimension(WIDTH, ROW_HEIGHT));

		add(search, BorderLayout.NORTH);
		add(scroll, BorderLayout.CENTER);
		add(empty, BorderLayout.SOUTH);
	}

	/**
	 * Start over with these commands and an empty search.
	 *
	 * @param recent    the recently used commands, which are listed first and set apart from the rest
	 * @param pinned    the pinned commands, which are listed after them, set apart too
	 * @param rest      every other command
	 * @param forQuery  further commands made from the text typed, listed after the ones matching it
	 * @param showIcons whether each command's icon is drawn before its name
	 */
	void show(List<Command> recent, List<Command> pinned, List<Command> rest,
		Function<String, List<Command>> forQuery, boolean showIcons)
	{
		this.showIcons = showIcons;
		this.recent = recent;
		this.pinned = pinned;
		this.commands = new ArrayList<>(recent);
		this.commands.addAll(pinned);
		this.commands.addAll(rest);
		this.forQuery = forQuery;
		if (search.getText().isEmpty())
		{
			refilter();
		}
		else
		{
			search.setText("");
		}
	}

	/**
	 * Lists again the commands made from what is typed, which may have changed since it was typed, keeping the
	 * selected row.
	 */
	void requery()
	{
		if (!isShowing())
		{
			return;
		}
		final int selected = list.getSelectedIndex();
		refilter();
		if (selected > 0 && selected < model.size())
		{
			select(selected);
		}
	}

	void focusSearch()
	{
		search.requestFocusInWindow();
	}

	JTextField getSearch()
	{
		return search;
	}

	private void refilter()
	{
		model.clear();
		for (Command command : CommandFilter.filter(commands, search.getText()))
		{
			model.addElement(command);
		}
		for (Command command : forQuery.apply(search.getText()))
		{
			model.addElement(command);
		}
		// a search puts the best matches first, wherever they came from
		sectionStarts = search.getText().isEmpty()
			? sectionStarts(List.of(recent.size(), pinned.size(), model.size() - recent.size() - pinned.size()))
			: Collections.emptySet();
		list.setVisibleRowCount(Math.min(model.size(), MAX_ROWS));
		scroll.setVisible(!model.isEmpty());
		empty.setVisible(model.isEmpty());
		select(0);
		listener.resized();
	}

	/**
	 * The first row of each section after the first, a line drawn above it, leaving out the empty ones.
	 *
	 * @param sizes how many rows each section has, in order
	 */
	static Set<Integer> sectionStarts(List<Integer> sizes)
	{
		final Set<Integer> starts = new HashSet<>();
		int row = 0;
		for (int size : sizes)
		{
			if (size > 0 && row > 0)
			{
				starts.add(row);
			}
			row += size;
		}
		return starts;
	}

	private void keyPressed(KeyEvent e)
	{
		if (listener.isHotkey(e))
		{
			listener.cancel();
			e.consume();
			return;
		}
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_DOWN:
				move(1);
				break;
			case KeyEvent.VK_UP:
				move(-1);
				break;
			case KeyEvent.VK_TAB:
				move(e.isShiftDown() ? -1 : 1);
				break;
			case KeyEvent.VK_PAGE_DOWN:
				select(Math.min(model.size() - 1, list.getSelectedIndex() + MAX_ROWS));
				break;
			case KeyEvent.VK_PAGE_UP:
				select(Math.max(0, list.getSelectedIndex() - MAX_ROWS));
				break;
			case KeyEvent.VK_ENTER:
				if (list.getSelectedValue() != null)
				{
					listener.run(list.getSelectedValue());
				}
				break;
			case KeyEvent.VK_ESCAPE:
				listener.cancel();
				break;
			default:
				return;
		}
		e.consume();
	}

	// wraps around at either end
	private void move(int by)
	{
		if (!model.isEmpty())
		{
			select(Math.floorMod(list.getSelectedIndex() + by, model.size()));
		}
	}

	private void select(int row)
	{
		if (row >= 0 && row < model.size())
		{
			list.setSelectedIndex(row);
			list.ensureIndexIsVisible(row);
		}
	}

	private int rowAt(MouseEvent e)
	{
		final int row = list.locationToIndex(e.getPoint());
		return row >= 0 && list.getCellBounds(row, row).contains(e.getPoint()) ? row : -1;
	}

	private final class Row extends JPanel implements ListCellRenderer<Command>
	{
		// the least of a row's width a detail is cut down to, however long the name
		private static final double DETAIL_SHARE = 0.35;

		private final JLabel title = new JLabel();
		private final JLabel detail = new JLabel();

		private Row()
		{
			setLayout(new BorderLayout(6, 0));

			title.setIconTextGap(6);
			// the clock of a recently used command goes after its detail, at the row's edge
			detail.setHorizontalTextPosition(SwingConstants.LEFT);
			detail.setIconTextGap(6);
			detail.setFont(FontManager.getRunescapeSmallFont());
			detail.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			add(title, BorderLayout.CENTER);
			add(detail, BorderLayout.EAST);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends Command> list, Command command, int index,
			boolean selected, boolean focused)
		{
			title.setText(command.getTitle());
			// a command without an icon still takes up the space of one, so that the names line up
			title.setIcon(!showIcons ? null : command.getIcon() == null ? NO_ICON : command.getIcon());
			title.setForeground(selected ? ColorScheme.BRAND_ORANGE : ColorScheme.TEXT_COLOR);
			detail.setText(command.getDetail());
			detail.setIcon(!showIcons ? null : recent.contains(command) ? Icons.RECENT
				: pinned.contains(command) ? Icons.PIN_FILLED : null);
			setBorder(sectionStarts.contains(index) ? SECTION_BORDER : ROW_BORDER);
			fitDetail();
			setBackground(selected ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			return this;
		}

		/**
		 * The name comes first: a long detail, such as a world's, is cut short with "..." to leave room for it, down
		 * to a share of the row so that a long name doesn't hide its detail altogether.
		 */
		private void fitDetail()
		{
			detail.setPreferredSize(null);
			final Insets insets = getBorder().getBorderInsets(this);
			// the palette's width: a component's own WIDTH is ImageObserver's flag, which would shadow it here
			final int room = PalettePanel.WIDTH - insets.left - insets.right - ((BorderLayout) getLayout()).getHgap();
			final Dimension wanted = detail.getPreferredSize();
			final int name = title.getPreferredSize().width;
			if (name + wanted.width > room)
			{
				final int width = Math.max(room - name, (int) (room * DETAIL_SHARE));
				detail.setPreferredSize(new Dimension(Math.min(wanted.width, width), wanted.height));
			}
		}
	}
}

package com.commandpalette;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/**
 * The commands pinned to the side panel's Pinned tab, across restarts.
 */
class PinnedCommands
{
	static final int MAX = 20;

	private static final String CONFIG_KEY = "pinned";
	private static final String SEPARATOR = "\n";

	private final ConfigManager configManager;

	@Inject
	PinnedCommands(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * The keys of the pinned commands, in the order they were pinned.
	 */
	List<String> load()
	{
		final String saved = configManager.getConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY);
		return saved == null || saved.isEmpty() ? Collections.emptyList() : Arrays.asList(saved.split(SEPARATOR));
	}

	void toggle(Command command)
	{
		if (command.getKey() == null)
		{
			return;
		}
		final List<String> keys = toggled(load(), command.getKey());
		if (keys.isEmpty())
		{
			configManager.unsetConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY);
		}
		else
		{
			configManager.setConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY, String.join(SEPARATOR, keys));
		}
	}

	/**
	 * Unpinned if it was pinned, otherwise pinned last, so long as there is room.
	 */
	static List<String> toggled(List<String> pinned, String key)
	{
		final List<String> keys = new ArrayList<>(pinned);
		if (!keys.remove(key) && keys.size() < MAX)
		{
			keys.add(key);
		}
		return keys;
	}
}

package com.commandpalette;

import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;

/**
 * The side panel's Pinned tab: commands to run with a click, the ones pinned and then the ones recently used, which
 * can be pinned from here.
 */
class PinnedPanel extends SideTab
{
	static final int RECENT_LISTED = 8;

	private final Supplier<List<Command>> commands;
	private final Consumer<Command> run;
	private final Supplier<List<String>> pinned;
	private final Consumer<Command> togglePin;
	private final Supplier<List<String>> recent;

	private final JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 4));

	/**
	 * @param commands  every command the palette would list now
	 * @param run       runs one
	 * @param pinned    the keys of the pinned commands
	 * @param togglePin pins a command, or unpins it
	 * @param recent    the keys of the commands last run, latest first
	 */
	PinnedPanel(Supplier<List<Command>> commands, Consumer<Command> run, Supplier<List<String>> pinned,
		Consumer<Command> togglePin, Supplier<List<String>> recent)
	{
		this.commands = commands;
		this.run = run;
		this.pinned = pinned;
		this.togglePin = togglePin;
		this.recent = recent;

		list.setOpaque(false);
		final JScrollPane scroll = scrolling(list);
		add(scroll, BorderLayout.CENTER);
	}

	@Override
	void refresh()
	{
		final List<Command> all = commands.get();
		final List<String> pinnedKeys = pinned.get();
		final List<Command> pins = RecentCommands.pick(all, pinnedKeys, PinnedCommands.MAX);
		final List<String> unpinnedRecent = new ArrayList<>(recent.get());
		unpinnedRecent.removeAll(pinnedKeys);
		final List<Command> recents = RecentCommands.pick(all, unpinnedRecent, RECENT_LISTED);

		list.removeAll();
		list.add(heading("Pinned"));
		if (pins.isEmpty())
		{
			list.add(note("Pin a command below to keep it here, a click away."));
		}
		pins.forEach(command -> list.add(row(command, true)));

		list.add(heading("Recently used"));
		if (recents.isEmpty())
		{
			list.add(note("The commands you run from the palette show up here, to run again or pin."));
		}
		recents.forEach(command -> list.add(row(command, false)));
		list.revalidate();
		list.repaint();
	}

	JPanel getList()
	{
		return list;
	}

	private JPanel row(Command command, boolean isPinned)
	{
		final JPanel row = row();
		row.setToolTipText(command.getDetail().isEmpty() ? command.getTitle() : command.getDetail());
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		final JLabel title = new JLabel(command.getTitle(), command.getIcon(), JLabel.LEADING);
		title.setForeground(ColorScheme.TEXT_COLOR);
		title.setIconTextGap(6);
		final JLabel detail = new JLabel(command.getDetail());
		detail.setFont(small());
		detail.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		detail.setBorder(BorderFactory.createEmptyBorder(0, command.getIcon() == null ? 0 : Icons.SIZE + 6, 0, 0));
		final JPanel text = new JPanel(new BorderLayout());
		text.setOpaque(false);
		text.add(title, BorderLayout.NORTH);
		if (!command.getDetail().isEmpty())
		{
			text.add(detail, BorderLayout.SOUTH);
		}

		final JButton pin = new JButton(isPinned ? Icons.PIN_FILLED : Icons.PIN);
		pin.setToolTipText(isPinned ? "Unpin" : "Pin");
		pin.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
		pin.setContentAreaFilled(false);
		pin.addActionListener(e ->
		{
			togglePin.accept(command);
			refresh();
		});

		row.add(text, BorderLayout.CENTER);
		row.add(pin, BorderLayout.EAST);
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1)
				{
					run.accept(command);
					refresh();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
		return row;
	}
}

package com.commandpalette;

import java.awt.event.InputEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.OSType;

/**
 * The "primary" shortcut modifier of the platform being played on: Cmd on a Mac, Ctrl elsewhere.
 *
 * <p>The Platform Keys plugin has a setting to force one platform's keys regardless of the computer. When that
 * plugin hasn't been switched off its choice is followed, so this plugin's hotkey uses the same modifier as its bank search.
 */
@Singleton
class PlatformModifier
{
	// Platform Keys' config group, its profile setting, and the values that setting takes (its KeyProfile enum)
	private static final String PLATFORM_KEYS_GROUP = "platformkeys";
	private static final String PLATFORM_KEYS_PROFILE = "profile";
	private static final String PROFILE_MAC = "MAC";
	private static final String PROFILE_WINDOWS = "WINDOWS";
	// Where RuneLite records whether the Platform Keys plugin is switched on
	private static final String RUNELITE_GROUP = "runelite";
	private static final String PLATFORM_KEYS_ENABLED = "platformkeysplugin";

	private final ConfigManager configManager;

	@Inject
	PlatformModifier(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * @return {@link InputEvent#META_DOWN_MASK} or {@link InputEvent#CTRL_DOWN_MASK}
	 */
	int get()
	{
		// plugins count as on until they have been switched off, so there may be no value at all
		final boolean platformKeysEnabled = !"false".equals(configManager.getConfiguration(RUNELITE_GROUP, PLATFORM_KEYS_ENABLED));
		return resolve(platformKeysEnabled ? configManager.getConfiguration(PLATFORM_KEYS_GROUP, PLATFORM_KEYS_PROFILE) : null,
			OSType.getOSType() == OSType.MacOS);
	}

	/**
	 * @param platformKeysProfile Platform Keys' profile setting, or null when that plugin isn't in use
	 */
	static int resolve(String platformKeysProfile, boolean onMac)
	{
		final boolean mac;
		if (PROFILE_MAC.equals(platformKeysProfile))
		{
			mac = true;
		}
		else if (PROFILE_WINDOWS.equals(platformKeysProfile))
		{
			mac = false;
		}
		else
		{
			// no override, or Platform Keys' own auto-detect
			mac = onMac;
		}
		return mac ? InputEvent.META_DOWN_MASK : InputEvent.CTRL_DOWN_MASK;
	}
}

package com.commandpalette;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import net.runelite.api.MenuAction;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Commands per plugin: one that turns it on or off, and one that opens its settings.
 */
class PluginCommands
{
	static final String KIND = "plugin:";
	static final String SETTINGS_KIND = "settings:";

	private static final Logger log = LoggerFactory.getLogger(PluginCommands.class);

	private final PluginManager pluginManager;
	private final ConfigManager configManager;
	private final EventBus eventBus;
	private final CommandPaletteConfig config;

	@Inject
	PluginCommands(PluginManager pluginManager, ConfigManager configManager, EventBus eventBus,
		CommandPaletteConfig config)
	{
		this.pluginManager = pluginManager;
		this.configManager = configManager;
		this.eventBus = eventBus;
		this.config = config;
	}

	/**
	 * A command per plugin that has settings, to open them in the Configuration panel.
	 */
	void collectSettings(List<Command> out)
	{
		final List<Command> commands = new ArrayList<>();
		for (Plugin plugin : pluginManager.getPlugins())
		{
			final PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
			if (descriptor == null || descriptor.hidden())
			{
				continue;
			}
			final Config pluginConfig = pluginManager.getPluginConfigProxy(plugin);
			if (pluginConfig != null && !configManager.getConfigDescriptor(pluginConfig).getItems().isEmpty())
			{
				commands.add(new Command(SETTINGS_KIND + descriptor.name(), descriptor.name(), "Open settings", Icons.COG,
					() -> openSettings(plugin)));
			}
		}
		commands.sort(Comparator.comparing(Command::getTitle, String.CASE_INSENSITIVE_ORDER));
		out.addAll(commands);
	}

	// The Configuration panel has no API, but it does open a plugin's settings when "Configure" is picked from
	// the right-click menu of one of that plugin's overlays. Tell it that happened, on an overlay nobody sees.
	private void openSettings(Plugin plugin)
	{
		final Overlay overlay = new Overlay(plugin)
		{
			@Override
			public Dimension render(Graphics2D graphics)
			{
				return null;
			}
		};
		eventBus.post(new OverlayMenuClicked(
			new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", plugin.getName()), overlay));
	}

	void collect(List<Command> out)
	{
		final List<Command> commands = new ArrayList<>();
		for (Plugin plugin : pluginManager.getPlugins())
		{
			final PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
			if (descriptor == null || descriptor.hidden() || plugin instanceof CommandPalettePlugin)
			{
				continue;
			}

			final boolean enabled = pluginManager.isPluginEnabled(plugin);
			// The configuration panel asks before turning off whatever a plugin conflicts with; leave those to it
			if (!enabled && hasEnabledConflict(plugin))
			{
				continue;
			}
			commands.add(new Command(KIND + descriptor.name(), descriptor.name(), enabled ? "Turn plugin off" : "Turn plugin on",
				enabled ? Icons.SWITCH_ON : Icons.SWITCH_OFF,
				() -> setEnabled(plugin, !enabled)));
		}
		commands.sort(Comparator.comparing(Command::getTitle, String.CASE_INSENSITIVE_ORDER));
		out.addAll(commands);
	}

	private boolean hasEnabledConflict(Plugin plugin)
	{
		for (Plugin conflict : pluginManager.conflictsForPlugin(plugin))
		{
			if (pluginManager.isPluginEnabled(conflict))
			{
				return true;
			}
		}
		return false;
	}

	private void setEnabled(Plugin plugin, boolean enabled)
	{
		if (config.confirmPluginToggle() && !confirm(plugin, enabled))
		{
			return;
		}

		pluginManager.setPluginEnabled(plugin, enabled);
		try
		{
			if (enabled)
			{
				pluginManager.startPlugin(plugin);
			}
			else
			{
				pluginManager.stopPlugin(plugin);
			}
		}
		catch (PluginInstantiationException ex)
		{
			log.warn("Error turning {} {}", plugin.getName(), enabled ? "on" : "off", ex);
		}
	}

	private static boolean confirm(Plugin plugin, boolean enabled)
	{
		final String action = enabled ? "Turn on" : "Turn off";
		final Object[] options = {action, "Cancel"};
		// Enter takes the default option, so a confirmed command is still hotkey, name, Enter, Enter
		return JOptionPane.showOptionDialog(Sidebar.findClientFrame(), action + " " + plugin.getName() + "?",
			"Command Palette", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE, null, options, options[0])
			== JOptionPane.YES_OPTION;
	}
}

package com.commandpalette;

/**
 * What was typed, split into an optional leading symbol that narrows the list and the words to search for.
 */
final class Query
{
	static final char PANELS = '#';
	static final char PLUGINS = '>';
	static final char WIKI = '?';

	private static final char NONE = 0;

	private final char prefix;
	private final String text;

	private Query(char prefix, String text)
	{
		this.prefix = prefix;
		this.text = text;
	}

	static Query parse(String typed)
	{
		final String trimmed = typed.trim();
		if (!trimmed.isEmpty())
		{
			final char first = trimmed.charAt(0);
			if (first == PANELS || first == PLUGINS || first == WIKI)
			{
				return new Query(first, trimmed.substring(1).trim());
			}
		}
		return new Query(NONE, trimmed);
	}

	boolean hasPrefix()
	{
		return prefix != NONE;
	}

	boolean isWiki()
	{
		return prefix == WIKI;
	}

	String getText()
	{
		return text;
	}

	/**
	 * Whether the prefix, if there is one, lets this command through.
	 */
	boolean allows(Command command)
	{
		switch (prefix)
		{
			case NONE:
				return true;
			case PANELS:
				return hasKind(command, SidebarCommands.PANEL_KIND) || hasKind(command, SidebarCommands.SIDEBAR_KIND);
			case PLUGINS:
				return hasKind(command, PluginCommands.KIND) || hasKind(command, PluginCommands.SETTINGS_KIND);
			default:
				return false;
		}
	}

	private static boolean hasKind(Command command, String kind)
	{
		return command.getKey() != null && command.getKey().startsWith(kind);
	}
}

package com.commandpalette;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/**
 * Remembers the last few commands run, across restarts.
 */
class RecentCommands
{
	// as many as the setting for how many to list goes up to, so that raising it brings older ones back
	static final int MAX = 20;

	private static final String CONFIG_KEY = "recent";
	private static final String SEPARATOR = "\n";

	private final ConfigManager configManager;

	@Inject
	RecentCommands(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * The keys of the commands last run, latest first.
	 */
	List<String> load()
	{
		final String saved = configManager.getConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY);
		return saved == null || saved.isEmpty() ? Collections.emptyList() : Arrays.asList(saved.split(SEPARATOR));
	}

	void record(Command command)
	{
		if (command.getKey() != null)
		{
			configManager.setConfiguration(CommandPaletteConfig.GROUP, CONFIG_KEY,
				String.join(SEPARATOR, withLatest(load(), command.getKey())));
		}
	}

	static List<String> withLatest(List<String> recent, String key)
	{
		final List<String> keys = new ArrayList<>(recent);
		keys.remove(key);
		keys.add(0, key);
		return keys.size() > MAX ? keys.subList(0, MAX) : keys;
	}

	/**
	 * The recently run ones of the commands, latest first and no more than the limit.
	 */
	static List<Command> pick(List<Command> commands, List<String> recent, int limit)
	{
		final List<Command> picked = new ArrayList<>();
		for (String key : recent)
		{
			if (picked.size() >= limit)
			{
				break;
			}
			for (Command command : commands)
			{
				if (key.equals(command.getKey()))
				{
					picked.add(command);
					break;
				}
			}
		}
		return picked;
	}
}

