/**
 * Keeps track of when this login began and what the account's xp was then, for a command that reports on it and
 * the side panel's Session tab.
 */
@Singleton
class SessionCommands
{
	/**
	 * The xp gained in one skill.
	 */
	static final class Gain
	{
		private final Skill skill;
		private final int xp;

		Gain(Skill skill, int xp)
		{
			this.skill = skill;
			this.xp = xp;
		}

		Skill getSkill()
		{
			return skill;
		}

		int getXp()
		{
			return xp;
		}
	}

	/**
	 * The session so far.
	 */
	static final class Snapshot
	{
		private final Duration time;
		private final List<Gain> gains;

		Snapshot(Duration time, List<Gain> gains)
		{
			this.time = time;
			this.gains = gains;
		}

		Duration getTime()
		{
			return time;
		}

		/**
		 * Most gained first.
		 */
		List<Gain> getGains()
		{
			return gains;
		}

		long getTotalXp()
		{
			return gains.stream().mapToLong(Gain::getXp).sum();
		}

		/**
		 * The xp an hour so far, or 0 for a session too short to say.
		 */
		long getXpPerHour()
		{
			final long seconds = time.getSeconds();
			return seconds < 60 ? 0 : getTotalXp() * 3600 / seconds;
		}
	}

	private static final int SKILLS_LISTED = 3;

	private final Client client;
	private final ClientThread clientThread;

	private Instant start;
	private int[] startXp;

	@Inject
	SessionCommands(Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
	}

	void collect(List<Command> out)
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			out.add(new Command("client:session", "Session summary", "Show in chat", Icons.CLOCK, () -> clientThread.invoke(() ->
			{
				if (start != null)
				{
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", summarize(
						Duration.between(start, Instant.now()), startXp, client.getSkillExperiences()), null);
				}
			})));
		}
	}

	/**
	 * Hands the session so far, or null when not logged in, to the consumer on the Swing thread.
	 */
	void snapshot(Consumer<Snapshot> then)
	{
		clientThread.invoke(() ->
		{
			final Snapshot snapshot = client.getGameState() != GameState.LOGGED_IN || start == null ? null
				: new Snapshot(Duration.between(start, Instant.now()), gains(startXp, client.getSkillExperiences()));
			SwingUtilities.invokeLater(() -> then.accept(snapshot));
		});
	}

	void reset()
	{
		start = null;
		startXp = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// hopping worlds carries on the same session; going back to the login screen ends it
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			reset();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// stats arrive a moment after logging in
		if (start == null && client.getOverallExperience() > 0)
		{
			start = Instant.now();
			startXp = client.getSkillExperiences().clone();
		}
	}

	static String summarize(Duration time, int[] startXp, int[] xp)
	{
		final Snapshot session = new Snapshot(time, gains(startXp, xp));
		final List<Gain> gained = session.getGains();

		final long minutes = time.toMinutes();
		final StringBuilder summary = new StringBuilder("Session: ")
			.append(minutes >= 60 ? minutes / 60 + "h " : "").append(minutes % 60).append("m logged in, ")
			.append(QuantityFormatter.formatNumber(session.getTotalXp())).append(" xp gained");
		if (!gained.isEmpty())
		{
			summary.append(" (");
			for (int n = 0; n < gained.size() && n < SKILLS_LISTED; n++)
			{
				final Gain gain = gained.get(n);
				summary.append(n > 0 ? ", " : "").append(gain.getSkill().getName()).append(' ')
					.append(QuantityFormatter.formatNumber(gain.getXp()));
			}
			summary.append(gained.size() > SKILLS_LISTED ? ", ...)" : ")");
		}
		return summary.toString();
	}

	/**
	 * The skills with xp gained, most first.
	 */
	static List<Gain> gains(int[] startXp, int[] xp)
	{
		final List<Gain> gained = new ArrayList<>();
		for (Skill skill : Skill.values())
		{
			final int i = skill.ordinal();
			if (skill != Skill.OVERALL && i < xp.length && i < startXp.length && xp[i] > startXp[i])
			{
				gained.add(new Gain(skill, xp[i] - startXp[i]));
			}
		}
		gained.sort((a, b) -> Integer.compare(b.getXp(), a.getXp()));
		return gained;
	}
}

package com.commandpalette;

import java.awt.BorderLayout;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.util.QuantityFormatter;

/**
 * The side panel's Session tab: how long this login has lasted and the xp gained in it, kept up to date.
 */
class SessionPanel extends SideTab
{
	private final Consumer<Consumer<SessionCommands.Snapshot>> snapshot;
	private final Function<Skill, Icon> skillIcon;

	private final JPanel content = new JPanel(new DynamicGridLayout(0, 1, 0, 4));

	/**
	 * @param snapshot  hands the session so far, or null when not logged in, to its argument on the Swing thread
	 * @param skillIcon a skill's small icon
	 */
	SessionPanel(Consumer<Consumer<SessionCommands.Snapshot>> snapshot, Function<Skill, Icon> skillIcon)
	{
		this.snapshot = snapshot;
		this.skillIcon = skillIcon;

		content.setOpaque(false);
		final JScrollPane scroll = scrolling(content);
		add(scroll, BorderLayout.CENTER);
	}

	@Override
	boolean isLive()
	{
		return true;
	}

	@Override
	void refresh()
	{
		snapshot.accept(this::show);
	}

	void show(SessionCommands.Snapshot session)
	{
		content.removeAll();
		content.add(heading("This session"));
		if (session == null)
		{
			content.add(note("Log in to start a session. It is counted from logging in, and carries on across"
				+ " world hops."));
		}
		else
		{
			content.add(stat("Logged in", Durations.format(Math.max(1, session.getTime().getSeconds())), Icons.CLOCK));
			content.add(stat("Xp gained", QuantityFormatter.formatNumber(session.getTotalXp()), null));
			content.add(stat("Xp an hour", session.getXpPerHour() > 0
				? QuantityFormatter.formatNumber(session.getXpPerHour()) : "-", null));

			content.add(heading("By skill"));
			if (session.getGains().isEmpty())
			{
				content.add(note("No xp gained yet."));
			}
			for (SessionCommands.Gain gain : session.getGains())
			{
				content.add(stat(gain.getSkill().getName(), QuantityFormatter.formatNumber(gain.getXp()),
					skillIcon.apply(gain.getSkill())));
			}
		}
		content.revalidate();
		content.repaint();
	}

	JPanel getContent()
	{
		return content;
	}

	private static JPanel stat(String name, String value, Icon icon)
	{
		final JPanel row = row();
		final JLabel label = new JLabel(name, icon, JLabel.LEADING);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setIconTextGap(6);
		final JLabel number = new JLabel(value);
		number.setForeground(ColorScheme.TEXT_COLOR);
		row.add(label, BorderLayout.CENTER);
		row.add(number, BorderLayout.EAST);
		return row;
	}
}

package com.commandpalette;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

/**
 * The plugin's side panel: the palette's commands that are better kept on screen, one tab each.
 */
class SidePanel extends PluginPanel
{
	// the panel's tooltip in the sidebar, which the palette finds it by
	static final String NAME = "Command Palette";

	enum Tab
	{
		TIMERS("Timers", Icons.TIMER),
		SESSION("Session", Icons.CLOCK),
		ANSWERS("Answers", Icons.EQUALS),
		PINNED("Pinned", Icons.PIN),
		CUSTOM("Custom", Icons.CUSTOM);

		private final String title;
		private final Icons icon;

		Tab(String title, Icons icon)
		{
			this.title = title;
			this.icon = icon;
		}

		String getTitle()
		{
			return title;
		}

		Icons getIcon()
		{
			return icon;
		}
	}

	private static final int TICK_MILLIS = 1000;

	private final Map<Tab, SideTab> contents;
	private final Map<Tab, MaterialTab> tabs = new EnumMap<>(Tab.class);
	private final MaterialTabGroup group;
	private final Supplier<String> hotkey;
	private final JLabel help;
	// counts down and updates the session while they are on screen
	private final Timer ticker = new Timer(TICK_MILLIS, e -> tick());
	private Tab selected = Tab.values()[0];

	/**
	 * @param contents what each tab shows, in the order of {@link Tab}
	 * @param hotkey   the hotkey that opens the palette, "Ctrl+P", or null if it has no name to show
	 * @param showHelp shows the help command's window
	 */
	SidePanel(Map<Tab, SideTab> contents, Supplier<String> hotkey, Runnable showHelp)
	{
		super(false);
		this.contents = new EnumMap<>(contents);
		this.hotkey = hotkey;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(BORDER_OFFSET, BORDER_OFFSET, BORDER_OFFSET, BORDER_OFFSET));

		final JPanel display = new JPanel(new BorderLayout());
		display.setOpaque(false);
		group = new MaterialTabGroup(display);
		group.setLayout(new GridLayout(1, Tab.values().length, 4, 0));
		for (Tab tab : Tab.values())
		{
			final MaterialTab materialTab = new MaterialTab(new ImageIcon(tab.getIcon().image()), group,
				this.contents.get(tab));
			materialTab.setToolTipText(tab.getTitle());
			materialTab.setOnSelectEvent(() ->
			{
				selected = tab;
				this.contents.get(tab).refresh();
				return true;
			});
			group.addTab(materialTab);
			tabs.put(tab, materialTab);
		}
		group.select(tabs.get(selected));

		// how to find out what else the palette can do, below every tab
		final JButton helpButton = new JButton("Help");
		helpButton.setFont(SideTab.small());
		helpButton.setToolTipText("Show every command and what to type for it");
		helpButton.addActionListener(e -> showHelp.run());
		final JPanel footer = new JPanel(new BorderLayout(6, 0));
		footer.setOpaque(false);
		footer.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 0, 0, 0)));
		// wrapped to the room the button leaves it
		help = new SideTab.Wrapping("", SideTab.TEXT_WIDTH - 6 - helpButton.getPreferredSize().width);
		help.setFont(SideTab.small());
		help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		footer.add(help, BorderLayout.CENTER);
		footer.add(helpButton, BorderLayout.EAST);
		updateHelp();

		add(group, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
	}

	@Override
	public void onActivate()
	{
		// the hotkey may have been changed in the settings since
		updateHelp();
		contents.get(selected).refresh();
		ticker.start();
	}

	@Override
	public void onDeactivate()
	{
		ticker.stop();
	}

	/**
	 * Shows the tab. The panel itself is opened through the sidebar.
	 */
	void select(Tab tab)
	{
		group.select(tabs.get(tab));
	}

	Tab getSelected()
	{
		return selected;
	}

	/**
	 * Updates the tab, if it is the one on screen.
	 */
	void refreshIfShowing(Tab tab)
	{
		if (isShowing() && selected == tab)
		{
			contents.get(tab).refresh();
		}
	}

	JLabel getHelp()
	{
		return help;
	}

	private void updateHelp()
	{
		final String keys = hotkey.get();
		help.setText("<html>Need help? Open the palette" + (keys == null ? "" : " with <b>" + keys + "</b>")
			+ " and type <b>help</b>, or click Help.</html>");
	}

	void stop()
	{
		ticker.stop();
	}

	private void tick()
	{
		if (isShowing() && contents.get(selected).isLive())
		{
			contents.get(selected).refresh();
		}
	}
}

package com.commandpalette;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Insets;
import java.awt.Rectangle;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * One tab of the {@link SidePanel}.
 */
abstract class SideTab extends JPanel
{
	/**
	 * How wide a tab's text can be: the panel's width inside its border, less a scroll bar in case there is one.
	 */
	static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET;
	/**
	 * How wide text can be in a {@link #row()} that has an icon button at its end.
	 */
	static final int ROW_TEXT_WIDTH = TEXT_WIDTH - 2 * 8 - 6 - (Icons.SIZE + 4);

	SideTab()
	{
		super(new BorderLayout(0, 6));
		setOpaque(false);
	}

	/**
	 * Show things as they are now. Called on the Swing thread when the tab is shown, and every second while it is
	 * if it is {@link #isLive()}.
	 */
	abstract void refresh();

	/**
	 * Whether what the tab shows changes by itself, as a countdown does.
	 */
	boolean isLive()
	{
		return false;
	}

	// shared looks

	static JLabel heading(String text)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.TEXT_COLOR);
		label.setFont(FontManager.getRunescapeBoldFont());
		return label;
	}

	/**
	 * Small grey text that wraps to the panel's width.
	 */
	static JLabel note(String text)
	{
		final JLabel label = new Wrapping("<html>" + text + "</html>", TEXT_WIDTH);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}

	/**
	 * Lets the content scroll up and down, never sideways: it is kept to the panel's width, and anything too long
	 * for it, such as a long name, is cut short with "..." rather than pushing what is beside it out of sight.
	 */
	static JScrollPane scrolling(JComponent content)
	{
		final WidthTracking wrapper = new WidthTracking();
		wrapper.add(content, BorderLayout.NORTH);
		final JScrollPane scroll = new JScrollPane(wrapper);
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		return scroll;
	}

	/**
	 * A box for one entry of a list, the way RuneLite's own panels draw them.
	 */
	static JPanel row()
	{
		final JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		return row;
	}

	/**
	 * Text to show as HTML, which is how it wraps, with the characters HTML gives a meaning to made plain.
	 */
	static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	/**
	 * A label whose HTML wraps at a width, and which asks for the height that takes. A plain HTML label asks for
	 * its whole text on one line, which widens whatever holds it.
	 */
	static final class Wrapping extends JLabel
	{
		private final int width;

		/**
		 * @param width the label's width, its icon and border included
		 */
		Wrapping(String text, int width)
		{
			super(text);
			this.width = width;
		}

		@Override
		public Dimension getPreferredSize()
		{
			final View view = (View) getClientProperty(BasicHTML.propertyKey);
			if (view == null || isPreferredSizeSet())
			{
				return super.getPreferredSize();
			}
			final Insets insets = getInsets();
			final int icon = getIcon() == null ? 0 : getIcon().getIconWidth() + getIconTextGap();
			view.setSize(Math.max(1, width - insets.left - insets.right - icon), 0);
			final int height = (int) Math.ceil(view.getPreferredSpan(View.Y_AXIS));
			return new Dimension(width,
				Math.max(height, getIcon() == null ? 0 : getIcon().getIconHeight()) + insets.top + insets.bottom);
		}
	}

	// takes the viewport's width, so that nothing in it is laid out wider
	private static final class WidthTracking extends JPanel implements Scrollable
	{
		private WidthTracking()
		{
			super(new BorderLayout());
			setOpaque(false);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return Math.max(16, visible.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.commandpalette;

import java.awt.Component;
import java.awt.Container;
import java.awt.Window;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.function.Predicate;
import javax.swing.JButton;
import javax.swing.JFrame;
import javax.swing.JTabbedPane;
import net.runelite.client.ui.ContainableFrame;

/**
 * RuneLite has no API for listing the side panels or opening another plugin's, so this works on the client
 * window's Swing components instead: the sidebar is a tabbed pane with one tab per panel.
 */
final class Sidebar
{
	// the title bar button that hides and shows the sidebar, as ClientUI labels it in either state
	private static final String OPEN_SIDEBAR_TOOLTIP = "Open sidebar";
	private static final String CLOSE_SIDEBAR_TOOLTIP = "Close sidebar";

	private Sidebar()
	{
	}

	static JFrame findClientFrame()
	{
		for (Window window : Window.getWindows())
		{
			if (window instanceof ContainableFrame)
			{
				return (JFrame) window;
			}
		}
		return null;
	}

	/**
	 * The sidebar within the client window, or null. Panels may hold tabbed panes of their own, so this takes the
	 * outermost one with its tabs on the right.
	 */
	static JTabbedPane find(Container window)
	{
		return (JTabbedPane) search(window, c -> c instanceof JTabbedPane
			&& ((JTabbedPane) c).getTabPlacement() == JTabbedPane.RIGHT);
	}

	/**
	 * Show the panel, opening the sidebar first if it is hidden.
	 *
	 * @param onForcedOpen run if the sidebar had to be shown without the client's own button
	 */
	static void open(Container window, JTabbedPane sidebar, Component panel, Runnable onForcedOpen)
	{
		final int index = sidebar.indexOfComponent(panel);
		if (index < 0)
		{
			return;
		}
		if (sidebar.isVisible())
		{
			sidebar.setSelectedIndex(index);
			return;
		}

		final JButton toggle = toggleButton(window, sidebar);
		if (toggle != null)
		{
			// While hidden the client only notes the selection; opening the sidebar is what activates the panel
			sidebar.setSelectedIndex(index);
			toggle.doClick(0);
		}
		else
		{
			// No button without the custom title bar. The client activates a panel when the selection changes
			// on a visible sidebar, so clear it first in case this panel was already the selected one.
			sidebar.setSelectedIndex(-1);
			sidebar.setVisible(true);
			sidebar.getParent().revalidate();
			sidebar.setSelectedIndex(index);
			onForcedOpen.run();
		}
	}

	/**
	 * The client's own button for hiding or showing the sidebar, or null: it only exists with the custom title bar.
	 */
	static JButton toggleButton(Container window, JTabbedPane sidebar)
	{
		final String tooltip = sidebar.isVisible() ? CLOSE_SIDEBAR_TOOLTIP : OPEN_SIDEBAR_TOOLTIP;
		return (JButton) search(window, c -> c instanceof JButton && tooltip.equals(((JButton) c).getToolTipText()));
	}

	// breadth first, so the outermost match wins
	private static Component search(Container root, Predicate<Component> test)
	{
		final Deque<Component> queue = new ArrayDeque<>();
		queue.add(root);
		while (!queue.isEmpty())
		{
			final Component component = queue.poll();
			if (test.test(component))
			{
				return component;
			}
			if (component instanceof Container)
			{
				for (Component child : ((Container) component).getComponents())
				{
					queue.add(child);
				}
			}
		}
		return null;
	}
}

package com.commandpalette;

import java.awt.Component;
import java.awt.Container;
import java.util.List;
import javax.inject.Inject;
import javax.swing.JButton;
import javax.swing.JTabbedPane;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneLiteConfig;

/**
 * A command per side panel, plus ones to close the open panel and to hide or show the whole sidebar.
 */
class SidebarCommands
{
	static final String PANEL_KIND = "panel:";
	static final String SIDEBAR_KIND = "sidebar:";
	static final String OPEN_DETAIL = "Open panel";
	static final String SHOWING_DETAIL = "Open panel (showing)";

	// what the client sets while the sidebar is hidden, so that it starts hidden next time
	private static final String SIDEBAR_CLOSED_KEY = "clientSidebarClosed";

	private final Runnable onForcedOpen;

	@Inject
	SidebarCommands(ConfigManager configManager)
	{
		this(() -> configManager.unsetConfiguration(RuneLiteConfig.GROUP_NAME, SIDEBAR_CLOSED_KEY));
	}

	SidebarCommands(Runnable onForcedOpen)
	{
		this.onForcedOpen = onForcedOpen;
	}

	void collect(Container window, List<Command> out)
	{
		final JTabbedPane sidebar = Sidebar.find(window);
		if (sidebar == null)
		{
			return;
		}

		final boolean showing = sidebar.isVisible() && sidebar.getSelectedIndex() >= 0;
		for (int i = 0; i < sidebar.getTabCount(); i++)
		{
			final Component panel = sidebar.getComponentAt(i);
			final String tooltip = sidebar.getToolTipTextAt(i);
			final String name = tooltip == null || tooltip.isEmpty() ? "Panel " + (i + 1) : tooltip;
			final boolean current = showing && sidebar.getSelectedIndex() == i;
			out.add(new Command(PANEL_KIND + name, name, current ? SHOWING_DETAIL : OPEN_DETAIL, sidebar.getIconAt(i),
				() -> Sidebar.open(window, sidebar, panel, onForcedOpen)));
		}
		if (showing)
		{
			out.add(new Command(SIDEBAR_KIND + "close", "Close side panel", "", Icons.CLOSE, () -> sidebar.setSelectedIndex(-1)));
		}

		final JButton toggle = Sidebar.toggleButton(window, sidebar);
		if (toggle != null)
		{
			out.add(new Command(SIDEBAR_KIND + "toggle", sidebar.isVisible() ? "Hide sidebar" : "Show sidebar", "", Icons.SIDEBAR, () -> toggle.doClick(0)));
		}
	}

	/**
	 * Opens the side panel of that name, if there is one.
	 */
	void open(Container window, String name)
	{
		final JTabbedPane sidebar = Sidebar.find(window);
		for (int i = 0; sidebar != null && i < sidebar.getTabCount(); i++)
		{
			if (name.equals(sidebar.getToolTipTextAt(i)))
			{
				Sidebar.open(window, sidebar, sidebar.getComponentAt(i), onForcedOpen);
				return;
			}
		}
	}
}

package com.commandpalette;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.stream.Collectors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;

/**
 * Timers started from the palette, each of which sends a notification and a chat message when it runs out. They last only as long as
 * the client is open.
 */
@Singleton
class Timers
{
	/**
	 * How long a timer is for, and what it is for.
	 */
	static final class Request
	{
		private final double seconds;
		private final String label;

		private Request(double seconds, String label)
		{
			this.seconds = seconds;
			this.label = label;
		}

		double getSeconds()
		{
			return seconds;
		}

		String getLabel()
		{
			return label;
		}

		/**
		 * "5m timer: herb run"
		 */
		String describe()
		{
			return Durations.format(seconds) + " timer" + (label.isEmpty() ? "" : ": " + label);
		}
	}

	/**
	 * A timer that is running, as it stood when asked for.
	 */
	static final class Status
	{
		private final Request request;
		private final long secondsLeft;
		private final Runnable cancel;

		private Status(Request request, long secondsLeft, Runnable cancel)
		{
			this.request = request;
			this.secondsLeft = secondsLeft;
			this.cancel = cancel;
		}

		Request getRequest()
		{
			return request;
		}

		long getSecondsLeft()
		{
			return secondsLeft;
		}

		void cancel()
		{
			cancel.run();
		}
	}

	private static final class Running
	{
		private final Request request;
		private final long endsAt;
		private ScheduledFuture<?> future;

		private Running(Request request, long endsAt)
		{
			this.request = request;
			this.endsAt = endsAt;
		}
	}

	private static final double MAX_SECONDS = 24 * 60 * 60;
	// "1 hour 30 minutes 15 seconds"
	private static final int MAX_DURATION_WORDS = 6;

	private final ScheduledExecutorService executor;
	private final Notifier notifier;
	private final Client client;
	private final ClientThread clientThread;
	// started and cancelled on the Swing thread, finished on the executor's
	private final List<Running> running = new CopyOnWriteArrayList<>();

	@Inject
	Timers(ScheduledExecutorService executor, Notifier notifier, Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.executor = executor;
		this.notifier = notifier;
	}

	/**
	 * @param text a length of time and then, optionally, what the timer is for: "5m herb run", "1h 30m", "90s".
	 *             A number on its own is in minutes.
	 * @return null if the text doesn't start with a length of time, or it is none at all or over a day
	 */
	static Request parse(String text)
	{
		final String[] words = text.trim().split("\\s+");
		for (int count = Math.min(words.length, MAX_DURATION_WORDS); count > 0; count--)
		{
			double seconds = Durations.parse(String.join(" ", List.of(words).subList(0, count)));
			if (seconds < 0 && count == 1 && words[0].matches("\\d+(\\.\\d+)?"))
			{
				seconds = Double.parseDouble(words[0]) * 60;
			}
			if (seconds >= 0)
			{
				final String label = String.join(" ", List.of(words).subList(count, words.length));
				return seconds >= 1 && seconds <= MAX_SECONDS ? new Request(seconds, label) : null;
			}
		}
		return null;
	}

	void start(Request request)
	{
		final long millis = Math.round(request.getSeconds() * 1000);
		final Running timer = new Running(request, System.currentTimeMillis() + millis);
		running.add(timer);
		timer.future = executor.schedule(() ->
		{
			// not if it was cancelled just as it ran out
			if (running.remove(timer))
			{
				final String message = request.getLabel().isEmpty()
					? "Your " + Durations.format(request.getSeconds()) + " timer is done"
					: "Timer done: " + request.getLabel();
				// RuneLite's notifications are, as they come, only sent while the client isn't being used, so
				// the chat is told too
				notifier.notify(message);
				clientThread.invoke(() ->
				{
					if (client.getGameState() == GameState.LOGGED_IN)
					{
						client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
					}
				});
			}
		}, millis, TimeUnit.MILLISECONDS);
	}

	/**
	 * A command to cancel each timer that is running, the one that ends soonest first.
	 */
	void collect(List<Command> out)
	{
		for (Status timer : running())
		{
			out.add(new Command("Cancel " + timer.getRequest().describe(),
				Durations.format(timer.getSecondsLeft()) + " left", Icons.TIMER, timer::cancel));
		}
	}

	/**
	 * The timers that are running, the one that ends soonest first.
	 */
	List<Status> running()
	{
		final long now = System.currentTimeMillis();
		return running.stream()
			.sorted((a, b) -> Long.compare(a.endsAt, b.endsAt))
			.map(timer -> new Status(timer.request, Math.max(1, Math.round((timer.endsAt - now) / 1000.0)),
				() -> cancel(timer)))
			.collect(Collectors.toList());
	}

	private void cancel(Running timer)
	{
		if (running.remove(timer))
		{
			timer.future.cancel(false);
		}
	}

	void reset()
	{
		for (Running timer : running)
		{
			cancel(timer);
		}
	}
}

package com.commandpalette;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;

/**
 * The side panel's Timers tab: start one, and see the ones running count down.
 */
class TimersPanel extends SideTab
{
	// the lengths of the buttons that start a timer in one click, in minutes
	private static final int[] QUICK_MINUTES = {1, 5, 10, 30, 60};

	private final Supplier<List<Timers.Status>> running;
	private final Consumer<Timers.Request> start;

	private final JTextField field = new JTextField();
	private final JLabel error = note("");
	private final JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 4));

	/**
	 * @param running the timers running now, soonest done first
	 * @param start   starts a timer
	 */
	TimersPanel(Supplier<List<Timers.Status>> running, Consumer<Timers.Request> start)
	{
		this.running = running;
		this.start = start;

		field.setToolTipText("A length and what it is for, such as 5m herb run");
		field.addActionListener(e -> startTyped());
		final JButton startButton = new JButton("Start");
		startButton.addActionListener(e -> startTyped());
		final JPanel typed = new JPanel(new BorderLayout(6, 0));
		typed.setOpaque(false);
		typed.add(field, BorderLayout.CENTER);
		typed.add(startButton, BorderLayout.EAST);

		final JPanel quick = new JPanel(new GridLayout(1, QUICK_MINUTES.length, 4, 0));
		quick.setOpaque(false);
		for (int minutes : QUICK_MINUTES)
		{
			final JButton button = new JButton(minutes >= 60 ? minutes / 60 + "h" : minutes + "m");
			button.setFont(small());
			button.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
			button.setToolTipText("Start a " + Durations.format(minutes * 60) + " timer,"
				+ " for what is typed above if anything");
			button.addActionListener(e -> startQuick(minutes));
			quick.add(button);
		}

		error.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		error.setVisible(false);

		final JPanel header = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		header.setOpaque(false);
		header.add(heading("Start a timer"));
		header.add(note("Type a length and what it is for, such as <b>5m herb run</b>, or click a length."));
		// a hidden error takes no room in a border layout, where it would in the grid
		final JPanel entry = new JPanel(new BorderLayout(0, 4));
		entry.setOpaque(false);
		entry.add(typed, BorderLayout.NORTH);
		entry.add(error, BorderLayout.SOUTH);
		header.add(entry);
		header.add(quick);
		header.add(heading("Running"));

		list.setOpaque(false);
		final JScrollPane scroll = scrolling(list);

		add(header, BorderLayout.NORTH);
		add(scroll, BorderLayout.CENTER);
	}

	@Override
	boolean isLive()
	{
		return true;
	}

	@Override
	void refresh()
	{
		list.removeAll();
		final List<Timers.Status> timers = running.get();
		if (timers.isEmpty())
		{
			list.add(note("No timers are running."));
		}
		for (Timers.Status timer : timers)
		{
			final JPanel row = row();
			final JLabel name = new JLabel(timer.getRequest().describe());
			name.setForeground(ColorScheme.TEXT_COLOR);
			final JLabel left = new JLabel(Durations.format(timer.getSecondsLeft()) + " left");
			left.setFont(small());
			left.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			final JPanel text = new JPanel(new BorderLayout());
			text.setOpaque(false);
			text.add(name, BorderLayout.NORTH);
			text.add(left, BorderLayout.SOUTH);

			final JButton cancel = new JButton(Icons.CLOSE);
			cancel.setToolTipText("Cancel this timer");
			cancel.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
			cancel.setContentAreaFilled(false);
			cancel.addActionListener(e ->
			{
				timer.cancel();
				refresh();
			});

			row.add(text, BorderLayout.CENTER);
			row.add(cancel, BorderLayout.EAST);
			list.add(row);
		}
		list.revalidate();
		list.repaint();
	}

	JTextField getField()
	{
		return field;
	}

	JLabel getError()
	{
		return error;
	}

	private void startTyped()
	{
		final Timers.Request request = Timers.parse(field.getText());
		if (request == null)
		{
			error.setText("<html>Start with a length of time, up to a day: <b>5m</b>, <b>1h 30m</b>, <b>90s</b>.</html>");
			error.setVisible(true);
			return;
		}
		started(request);
	}

	private void startQuick(int minutes)
	{
		// whatever is typed is what the timer is for
		final String typed = field.getText().trim();
		final Timers.Request request = Timers.parse(minutes + "m " + typed);
		if (request != null)
		{
			started(request);
		}
	}

	private void started(Timers.Request request)
	{
		start.accept(request);
		field.setText("");
		error.setVisible(false);
		refresh();
	}
}

package com.commandpalette;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.Icon;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.http.api.item.ItemPrice;

/**
 * Commands made from what was typed rather than found by it: a sum, the odds of a dry streak, the tax on a sale,
 * ticks as time, a timer to start, an item to price, a level to reach, and failing all else a wiki search.
 */
class TypedCommands
{
	private static final String WIKI_SEARCH = "https://oldschool.runescape.wiki/?utm_source=runelite&search=";
	private static final Pattern ITEM = Pattern.compile("(?:alch|price)\\s+(.+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern DRY = Pattern.compile("dry\\s+(.+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern TAX = Pattern.compile("tax\\s+(.+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern TICKS = Pattern.compile("ticks?\\s+(.+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern TIMER = Pattern.compile("timer\\s+(.+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern XP = Pattern.compile("xp\\s+(.+)", Pattern.CASE_INSENSITIVE);
	private static final int MAX_ITEMS = 5;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;
	private final CommandPaletteConfig config;
	private final Timers timers;
	private final Answers answers;
	private final VariableResolver variables;

	private Runnable onIconLoaded = () -> {};
	private Runnable onVariablesResolved = () -> {};
	// what was typed with variables in it, and the last text filled in for it, both on the Swing thread
	private String asked;
	private String resolvedFor;
	private String resolved;

	@Inject
	TypedCommands(Client client, ClientThread clientThread, ItemManager itemManager, SkillIconManager skillIconManager,
		CommandPaletteConfig config, Timers timers, Answers answers, VariableResolver variables)
	{
		this.variables = variables;
		this.answers = answers;
		this.timers = timers;
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;
		this.config = config;
	}

	/**
	 * @param onIconLoaded run, on any thread, when a command's icon has finished loading and wants repainting
	 */
	void setOnIconLoaded(Runnable onIconLoaded)
	{
		this.onIconLoaded = onIconLoaded;
	}

	/**
	 * @param onVariablesResolved run on the Swing thread when variables typed in have been filled in, to list
	 *                            them again
	 */
	void setOnVariablesResolved(Runnable onVariablesResolved)
	{
		this.onVariablesResolved = onVariablesResolved;
	}

	/**
	 * Forgets what variables were last filled in as, so that they are read again: the palette is opening.
	 */
	void forgetVariables()
	{
		resolvedFor = null;
		resolved = null;
	}

	List<Command> forQuery(String typed)
	{
		final Query query = Query.parse(typed);
		if (query.isWiki())
		{
			return wikiSearch(query.getText());
		}
		if (query.hasPrefix() || query.getText().isEmpty())
		{
			return Collections.emptyList();
		}

		final List<Command> commands = new ArrayList<>();
		if (config.lookupCommands())
		{
			variables(query.getText(), commands);
			calculation(query.getText(), commands);
			dryStreak(query.getText(), commands);
			answer(TAX, query.getText(), GeTax::describe, Icons.EQUALS, commands);
			answer(TICKS, query.getText(), Durations::convertTicks, Icons.TIMER, commands);
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				items(query.getText(), commands);
				xpToLevel(query.getText(), commands);
			}
		}
		if (config.timerCommands())
		{
			timer(query.getText(), commands);
		}
		if (config.wikiSearch())
		{
			commands.addAll(wikiSearch(query.getText()));
		}
		return commands;
	}

	static List<Command> wikiSearch(String text)
	{
		final String search = text.trim();
		if (search.isEmpty())
		{
			return Collections.emptyList();
		}
		return Collections.singletonList(new Command("Search the wiki for \"" + search + "\"", "", Icons.SEARCH,
			() -> LinkBrowser.browse(WIKI_SEARCH + URLEncoder.encode(search, StandardCharsets.UTF_8))));
	}

	// "{kc zulrah}" as its value: read on the client thread, and listed once it is back
	private void variables(String text, List<Command> out)
	{
		if (!VariableResolver.hasVariables(text))
		{
			return;
		}
		if (!text.equals(resolvedFor))
		{
			if (!text.equals(asked))
			{
				asked = text;
				variables.resolveLater(text, false, answer ->
				{
					resolvedFor = text;
					resolved = answer;
					asked = null;
					onVariablesResolved.run();
				});
			}
			return;
		}
		if (resolved.equals(text))
		{
			// nothing in it is a variable that could be read just now
			return;
		}
		final String value = resolved;
		final String answer = isOneToken(text) ? text + " = " + value : value;
		out.add(new Command(value, "Copy", Icons.BRACES, () ->
		{
			copy(value);
			answers.add(answer, value, Icons.BRACES);
		}));
	}

	private static boolean isOneToken(String text)
	{
		final List<int[]> tokens = VariableResolver.tokens(text);
		return tokens.size() == 1 && tokens.get(0)[0] == 0 && tokens.get(0)[1] == text.length();
	}

	private void calculation(String text, List<Command> out)
	{
		final Double value = Calculator.evaluate(text);
		if (value != null)
		{
			final String answer = text.trim() + " = " + Calculator.format(value);
			out.add(new Command("= " + Calculator.format(value), "Copy", Icons.EQUALS, () ->
			{
				copy(Calculator.plain(value));
				answers.add(answer, Calculator.plain(value), Icons.EQUALS);
			}));
		}
	}

	private void dryStreak(String text, List<Command> out)
	{
		final Matcher matcher = DRY.matcher(text);
		final DryStreak streak = matcher.matches() ? DryStreak.parse(matcher.group(1)) : null;
		if (streak == null)
		{
			return;
		}
		if (streak.hasKills())
		{
			out.add(copying(streak.describeDry(), Icons.DICE));
		}
		out.add(copying(streak.describeMilestones(), Icons.DICE));
	}

	// for a keyword followed by something the function can answer
	private void answer(Pattern pattern, String text, Function<String, String> function, Icon icon,
		List<Command> out)
	{
		final Matcher matcher = pattern.matcher(text);
		final String answer = matcher.matches() ? function.apply(matcher.group(1)) : null;
		if (answer != null)
		{
			out.add(copying(answer, icon));
		}
	}

	private void timer(String text, List<Command> out)
	{
		final Matcher matcher = TIMER.matcher(text);
		final Timers.Request request = matcher.matches() ? Timers.parse(matcher.group(1)) : null;
		if (request == null)
		{
			return;
		}
		out.add(new Command("Start " + request.describe(), "Notify when done", Icons.TIMER, () -> startTimer(request)));
	}

	/**
	 * Starts the timer, and says so in the chat when logged in.
	 */
	void startTimer(Timers.Request request)
	{
		timers.start(request);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				say("Started " + request.describe());
			}
		});
	}

	/**
	 * Keeps the answer in the side panel's Answers tab, and shows it in the chat when logged in, where only the
	 * player sees it.
	 */
	void show(String answer, Icon icon)
	{
		answers.add(answer, icon);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				say(answer);
			}
		});
	}

	// a command that is its own answer, and copies it
	private Command copying(String answer, Icon icon)
	{
		return new Command(answer, "Copy", icon, () ->
		{
			copy(answer);
			answers.add(answer, icon);
		});
	}

	private static void copy(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}

	private void items(String text, List<Command> out)
	{
		final Matcher matcher = ITEM.matcher(text);
		if (!matcher.matches())
		{
			return;
		}

		final String name = matcher.group(1).trim().toLowerCase(Locale.ROOT);
		final List<ItemPrice> items = itemManager.search(name);
		items.sort(closestTo(name));
		for (ItemPrice item : items.subList(0, Math.min(items.size(), MAX_ITEMS)))
		{
			final AsyncBufferedImage image = itemManager.getImage(item.getId());
			// item images are drawn on the client thread a moment later
			image.onLoaded(onIconLoaded);
			final Icon icon = Icons.of(image);
			out.add(new Command(item.getName(), "Price and alch value", icon, () -> clientThread.invoke(() ->
			{
				final int alch = itemManager.getItemComposition(item.getId()).getHaPrice();
				final String answer = item.getName() + ": GE "
					+ QuantityFormatter.formatNumber(itemManager.getItemPrice(item.getId()))
					+ " gp, high alch " + QuantityFormatter.formatNumber(alch) + " gp";
				say(answer);
				answers.add(answer, icon);
			})));
		}
	}

	// the item called exactly that, then those starting with it, then the shortest names
	static Comparator<ItemPrice> closestTo(String name)
	{
		return Comparator
			.comparing((ItemPrice item) -> !item.getName().equalsIgnoreCase(name))
			.thenComparing(item -> !item.getName().toLowerCase(Locale.ROOT).startsWith(name))
			.thenComparingInt(item -> item.getName().length())
			.thenComparing(ItemPrice::getName);
	}

	private void xpToLevel(String text, List<Command> out)
	{
		final Matcher matcher = XP.matcher(text);
		if (!matcher.matches())
		{
			return;
		}
		final LevelGoal goal = LevelGoal.parse(matcher.group(1));
		if (goal == null)
		{
			return;
		}

		final Skill skill = goal.getSkill();
		final int xp = client.getSkillExperience(skill);
		// with no level given, the next one
		final int level = goal.getLevel() > 0 ? goal.getLevel()
			: Math.min(Experience.getLevelForXp(xp) + 1, Experience.MAX_VIRT_LEVEL);
		final int remaining = Experience.getXpForLevel(level) - xp;
		final String answer = remaining > 0
			? skill.getName() + ": " + QuantityFormatter.formatNumber(remaining) + " xp to level " + level
			: skill.getName() + " is already level " + level + " or higher";
		final Icon icon = Icons.of(skillIconManager.getSkillImage(skill, true));
		out.add(new Command(answer, "Show in chat", icon, () ->
		{
			answers.add(answer, icon);
			clientThread.invoke(() -> say(answer));
		}));
	}

	// on the client thread
	private void say(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}
}

package com.commandpalette;

import java.util.List;

/**
 * The variables to pick from in the Custom tab. Ground Marker Variables' are a selection of its own, which its
 * README lists in full.
 */
final class VariableCatalog
{
	static final class Variable
	{
		private final String token;
		private final String description;

		Variable(String token, String description)
		{
			this.token = token;
			this.description = description;
		}

		/**
		 * What is put in the command, an example where the variable takes a name: "{kc zulrah}".
		 */
		String getToken()
		{
			return token;
		}

		String getDescription()
		{
			return description;
		}
	}

	/**
	 * What is typed after the command's name, which is filled in before the rest.
	 */
	static final Variable TEXT = new Variable(CustomCommand.TEXT,
		"What you type after the command's name: ge abyssal whip");

	static final List<Variable> OWN = List.of(
		new Variable("{rsn}", "Your name"),
